  COLS, ROWS, HEX_SIZE, HEX_W, BOARD_PAD, BOARD_W, BOARD_H, TERRAIN,
  terrainAt, terrainKeyAt, isRoad, isBaseCell, MAP_LABELS, CRATERS, BRIDGE
