  }
}

function drawPaddy(ctx, x, y, c, r) {
  const g = ctx.createLinearGradient(x - HEX_SIZE, y - HEX_SIZE, x + HEX_SIZE, y + HEX_SIZE)
  g.addColorStop(0, '#5d6c3b')
  g.addColorStop(0.5, '#4f6034')
  g.addColorStop(1, '#45552d')
  ctx.fillStyle = g
  ctx.fillRect(x - HEX_SIZE, y - HEX_SIZE, HEX_SIZE * 2, HEX_SIZE * 2)

  // Water bands
  for (let i = 0; i < 4; i++) {
    const py = y - 30 + i * 17 + h2(c, r, i) * 5
    ctx.fillStyle = `rgba(126,150,104,${0.08 + h2(c, r, i + 10) * 0.07})`
    ctx.beginPath()
    ctx.moveTo(x - HEX_SIZE, py)
    ctx.quadraticCurveTo(x - 10, py - 5, x + 16, py + 1)
    ctx.quadraticCurveTo(x + 38, py + 4, x + HEX_SIZE, py - 2)
    ctx.lineTo(x + HEX_SIZE, py + 7)
    ctx.quadraticCurveTo(x + 20, py + 12, x - 6, py + 6)
    ctx.quadraticCurveTo(x - 30, py + 2, x - HEX_SIZE, py + 7)
    ctx.closePath()
    ctx.fill()
  }
  // Rice rows
  ctx.strokeStyle = 'rgba(112,136,73,.72)'
  ctx.lineWidth = 1.1
  for (let row = 0; row < 5; row++) {
    const py = y - 24 + row * 12
    ctx.beginPath()
    for (let col = 0; col < 8; col++) {
      const px = x - 30 + col * 9 + h2(c, r, row * 10 + col) * 2
      ctx.moveTo(px, py)
      ctx.lineTo(px + 1.5, py - 4 - h2(c, r, row + col * 4) * 3)
    }
    ctx.stroke()
  }
  // Dikes
  ctx.strokeStyle = 'rgba(64,64,38,.85)'
  ctx.lineWidth = 3
  ctx.beginPath()
  ctx.moveTo(x - 38, y - 30)
  ctx.quadraticCurveTo(x - 5, y - 36, x + 36, y - 28)
  ctx.stroke()
  ctx.strokeStyle = 'rgba(90,90,54,.7)'
  ctx.lineWidth = 1.2
  ctx.beginPath()
  ctx.moveTo(x - 38, y - 32)
  ctx.quadraticCurveTo(x - 5, y - 38, x + 36, y - 30)
  ctx.stroke()
  // Specular glints
  ctx.fillStyle = 'rgba(200,218,165,.13)'
  for (let i = 0; i < 6; i++) {
    ctx.fillRect(x - 30 + h2(c, r, i + 20) * 60, y - 24 + h2(c, r, i + 40) * 48, 5 + h2(c, r, i) * 7, 1)
  }
}

function drawHill(ctx, x, y, c, r) {
  const g = ctx.createRadialGradient(x - 8, y - 14, 2, x, y, HEX_SIZE * 1.05)
  g.addColorStop(0, '#706a43')
  g.addColorStop(0.6, '#5d5838')
  g.addColorStop(1, '#49452c')
  ctx.fillStyle = g
  ctx.fillRect(x - HEX_SIZE, y - HEX_SIZE, HEX_SIZE * 2, HEX_SIZE * 2)

  // Contour lines
  for (let i = 0; i < 4; i++) {
    const rr = 12 + i * 8 + h2(c, r, i) * 3
    ctx.strokeStyle = `rgba(197,184,132,${0.13 - i * 0.015})`
    ctx.lineWidth = 1.1
    ctx.beginPath()
    ctx.ellipse(x - 3, y + 2, rr, rr * 0.7, -0.24, 0, TAU)
    ctx.stroke()
  }
  // Exposed rock and scrub
  for (let i = 0; i < 7; i++) {
    const px = x + (h2(c, r, i + 20) - 0.5) * 62
    const py = y + (h2(c, r, i + 40) - 0.5) * 48
    if (i % 3 === 0) {
      ctx.fillStyle = 'rgba(120,113,85,.65)'
      ctx.beginPath()
      ctx.moveTo(px, py)
      ctx.lineTo(px + 5, py - 3)
      ctx.lineTo(px + 7, py + 3)
      ctx.closePath()
      ctx.fill()
    } else {
      ctx.strokeStyle = 'rgba(114,124,70,.55)'
      ctx.lineWidth = 1
      ctx.beginPath()
      ctx.moveTo(px, py)
      ctx.lineTo(px + 1, py - 5)
      ctx.stroke()
    }
  }
}

function drawVillage(ctx, x, y, c, r) {
  const g = ctx.createLinearGradient(x - 30, y - 30, x + 30, y + 30)
  g.addColorStop(0, '#7a6643')
  g.addColorStop(1, '#5d4c32')
  ctx.fillStyle = g
  ctx.fillRect(x - HEX_SIZE, y - HEX_SIZE, HEX_SIZE * 2, HEX_SIZE * 2)

  // Dirt paths
  ctx.strokeStyle = 'rgba(126,108,73,.45)'
  ctx.lineWidth = 6
  ctx.beginPath()
  ctx.moveTo(x - 36, y + 20)
  ctx.quadraticCurveTo(x - 4, y + 2, x + 34, y - 24)
  ctx.stroke()

  // Hooches
  const houses = [
    { dx: -20, dy: -13, w: 24, h: 16, rot: -0.12 },
    { dx: 17, dy: 14, w: 20, h: 13, rot: 0.08 }
  ]
  for (let i = 0; i < houses.length; i++) {
    const ho = houses[i]
    ctx.save()
    ctx.translate(x + ho.dx, y + ho.dy)
    ctx.rotate(ho.rot + (h2(c, r, i) - 0.5) * 0.18)
    ctx.fillStyle = 'rgba(24,20,12,.28)'
    ctx.fillRect(-ho.w / 2 + 3, -ho.h / 2 + 4, ho.w, ho.h)
    ctx.fillStyle = i % 2 ? '#8d7647' : '#9a7f4b'
    ctx.fillRect(-ho.w / 2, -ho.h / 2, ho.w, ho.h)
    ctx.strokeStyle = 'rgba(72,53,28,.85)'
    ctx.lineWidth = 1.2
    ctx.strokeRect(-ho.w / 2, -ho.h / 2, ho.w, ho.h)
    // ridge + thatch
    ctx.strokeStyle = 'rgba(63,45,24,.65)'
    ctx.lineWidth = 1
    ctx.beginPath()
    ctx.moveTo(-ho.w / 2, 0)
    ctx.lineTo(ho.w / 2, 0)
    ctx.stroke()
    for (let k = -2; k <= 2; k++) {
      ctx.beginPath()
      ctx.moveTo(k * 5, -ho.h / 2 + 1)
      ctx.lineTo(k * 5, ho.h / 2 - 1)
      ctx.stroke()
    }
    ctx.restore()
  }

  // Palms
  for (let i = 0; i < 3; i++) {
    const px = x + (h2(c, r, i + 30) - 0.5) * 60
    const py = y + (h2(c, r, i + 50) - 0.5) * 46
    ctx.strokeStyle = 'rgba(48,39,24,.9)'
    ctx.lineWidth = 2
    ctx.beginPath()
    ctx.moveTo(px, py + 7)
    ctx.quadraticCurveTo(px + 3, py - 5, px + 1, py - 15)
    ctx.stroke()
    ctx.strokeStyle = 'rgba(58,84,44,.85)'
    ctx.lineWidth = 1.4
    for (let f = 0; f < 6; f++) {
      const a = (f / 6) * TAU + h2(c, r, f) * 0.3
      ctx.beginPath()
      ctx.moveTo(px + 1, py - 15)
      ctx.quadraticCurveTo(px + Math.cos(a) * 8, py - 18 + Math.sin(a) * 4, px + Math.cos(a) * 13, py - 15 + Math.sin(a) * 8)
      ctx.stroke()
    }
  }

  // Hedgerow
  ctx.fillStyle = 'rgba(46,68,34,.7)'
  for (let i = 0; i < 5; i++) {
    const px = x - 30 + i * 15
    const py = y + 28 + (h2(c, r, i + 70) - 0.5) * 4
    ctx.beginPath()
    ctx.arc(px, py, 3.4, 0, TAU)
    ctx.fill()
  }
}

function drawBaseGround(ctx, x, y, c, r) {
  const g = ctx.createLinearGradient(x - HEX_SIZE, y - HEX_SIZE, x + HEX_SIZE, y + HEX_SIZE)
  g.addColorStop(0, '#73694c')
  g.addColorStop(0.55, '#675e44')
  g.addColorStop(1, '#575039')
  ctx.fillStyle = g
  ctx.fillRect(x - HEX_SIZE, y - HEX_SIZE, HEX_SIZE * 2, HEX_SIZE * 2)

  // gravel
  ctx.fillStyle = 'rgba(31,29,19,.22)'
  for (let i = 0; i < 14; i++) {
    const px = x + (h2(c, r, i) - 0.5) * 70
    const py = y + (h2(c, r, i + 20) - 0.5) * 60
    ctx.fillRect(px, py, 1.4, 1.2)
  }
  ctx.fillStyle = 'rgba(190,178,134,.12)'
  for (let i = 0; i < 7; i++) {
    ctx.fillRect(x + (h2(c, r, i + 40) - 0.5) * 64, y + (h2(c, r, i + 60) - 0.5) * 54, 2.3, 1.4)
  }

  // Revetments, stores, and tents, keyed to their hex.
  if (c === 1 && r === 3) {
    // Command tent
    ctx.save()
    ctx.translate(x - 2, y - 5)
    ctx.fillStyle = 'rgba(24,22,14,.3)'
    ctx.fillRect(-16, -8, 34, 24)
    ctx.fillStyle = '#6d7448'
    ctx.beginPath()
    ctx.moveTo(-16, 8)
    ctx.lineTo(-16, -6)
    ctx.lineTo(2, -12)
    ctx.lineTo(18, -6)
    ctx.lineTo(18, 8)
    ctx.closePath()
    ctx.fill()
    ctx.strokeStyle = 'rgba(38,44,28,.8)'
    ctx.lineWidth = 1
    ctx.stroke()
    ctx.beginPath()
    ctx.moveTo(2, -12)
    ctx.lineTo(2, 8)
    ctx.stroke()
    ctx.restore()
  }
  if (c === 0 && r === 3) {
    // Radio mast and crates
    ctx.strokeStyle = 'rgba(32,36,22,.9)'
    ctx.lineWidth = 1.5
    ctx.beginPath()
    ctx.moveTo(x + 6, y + 14)
    ctx.lineTo(x + 1, y - 26)
    ctx.stroke()
    ctx.strokeStyle = 'rgba(210,202,166,.4)'
    ctx.lineWidth = 0.8
    for (let i = 0; i < 3; i++) {
      ctx.beginPath()
      ctx.moveTo(x + 4 - i * 2, y - 6 - i * 7)
      ctx.lineTo(x + 13 + i * 3, y - 10 - i * 7)
      ctx.stroke()
    }
    ctx.fillStyle = 'rgba(93,78,48,.95)'
    ctx.fillRect(x - 24, y + 10, 10, 7)
    ctx.fillRect(x - 18, y + 14, 9, 6)
    ctx.strokeStyle = 'rgba(38,32,19,.7)'
    ctx.lineWidth = 0.8
    ctx.strokeRect(x - 24, y + 10, 10, 7)
  }
  if (c === 2 && r === 4) {
    // Bunker revetment
    ctx.strokeStyle = 'rgba(92,83,55,.9)'
    ctx.lineWidth = 5
    ctx.beginPath()
    ctx.arc(x, y, 31, -0.7, Math.PI + 0.7)
    ctx.stroke()
    for (let i = 0; i < 8; i++) {
      const a = -0.55 + i * 0.36
      ctx.fillStyle = i % 2 ? 'rgba(160,146,103,.9)' : 'rgba(181,165,118,.9)'
      ctx.beginPath()
      ctx.ellipse(x + Math.cos(a) * 31, y + Math.sin(a) * 31, 4.4, 3, a, 0, TAU)
      ctx.fill()
    }
    // fuel drums
    ctx.fillStyle = 'rgba(89,96,67,.9)'
    ctx.beginPath()
    ctx.arc(x - 26, y + 25, 4, 0, TAU)
    ctx.arc(x - 18, y + 27, 4, 0, TAU)
    ctx.fill()
  }
  if (c === 3 && r === 4) {
    // Vehicle revetment and crates near the tank park
    ctx.strokeStyle = 'rgba(99,90,59,.9)'
    ctx.lineWidth = 4
    ctx.beginPath()
    ctx.moveTo(x - 27, y - 20)
    ctx.lineTo(x - 27, y + 22)
    ctx.stroke()
    ctx.fillStyle = 'rgba(117,99,60,.9)'
    ctx.fillRect(x + 10, y - 22, 15, 8)
    ctx.fillRect(x + 14, y - 11, 12, 7)
    ctx.strokeStyle = 'rgba(45,37,21,.7)'
    ctx.lineWidth = 0.8
    ctx.strokeRect(x + 10, y - 22, 15, 8)
  }
  if (c === 4 && r === 5) {
    // Ammo stack and fuel bladders
    ctx.fillStyle = 'rgba(91,84,53,.95)'
    ctx.fillRect(x - 20, y + 15, 14, 8)
    ctx.fillRect(x - 14, y + 24, 11, 6)
    ctx.strokeStyle = 'rgba(39,33,19,.7)'
    ctx.lineWidth = 0.8
    ctx.strokeRect(x - 20, y + 15, 14, 8)
    ctx.fillStyle = 'rgba(78,83,56,.9)'
    ctx.beginPath()
    ctx.ellipse(x + 17, y + 18, 9, 5, 0.2, 0, TAU)
    ctx.fill()
  }
  if (c === 3 && r === 3) {
    // Canvas lean-to
    ctx.fillStyle = 'rgba(100,102,68,.85)'
    ctx.beginPath()
    ctx.moveTo(x - 12, y + 12)
    ctx.lineTo(x - 4, y - 10)
    ctx.lineTo(x + 16, y - 4)
    ctx.lineTo(x + 10, y + 13)
    ctx.closePath()
    ctx.fill()
  }
}

function drawGrass(ctx, x, y, c, r) {
  const g = ctx.createLinearGradient(x - HEX_SIZE, y - HEX_SIZE, x + HEX_SIZE, y + HEX_SIZE)
  g.addColorStop(0, '#59653a')
  g.addColorStop(1, '#47532e')
  ctx.fillStyle = g
  ctx.fillRect(x - HEX_SIZE, y - HEX_SIZE, HEX_SIZE * 2, HEX_SIZE * 2)

  for (let i = 0; i < 46; i++) {
    const px = x + (h2(c, r, i) - 0.5) * 76
    const py = y + (h2(c, r, i + 100) - 0.5) * 60
    const len = 3 + h2(c, r, i + 200) * 5
    const hue = h2(c, r, i + 300)
    ctx.strokeStyle = hue > 0.6 ? 'rgba(132,143,79,.58)' : hue > 0.3 ? 'rgba(94,110,56,.7)' : 'rgba(65,80,38,.75)'
    ctx.lineWidth = 1
    ctx.beginPath()
    ctx.moveTo(px, py)
    ctx.lineTo(px + (h2(c, r, i + 400) - 0.5) * 3, py - len)
    ctx.stroke()
  }
  // Shrubs
  for (let i = 0; i < 3; i++) {
    const px = x + (h2(c, r, i + 500) - 0.5) * 54
    const py = y + (h2(c, r, i + 600) - 0.5) * 42
    ctx.fillStyle = 'rgba(54,73,36,.7)'
    ctx.beginPath()
    ctx.arc(px, py, 3 + h2(c, r, i) * 3, 0, TAU)
    ctx.fill()
  }
}

function drawWater(ctx, x, y, c, r, bridge = false) {
  const g = ctx.createLinearGradient(x - 30, y - 30, x + 32, y + 34)
  g.addColorStop(0, '#386168')
  g.addColorStop(0.45, '#2d535a')
  g.addColorStop(1, '#224246')
  ctx.fillStyle = g
  ctx.fillRect(x - HEX_SIZE, y - HEX_SIZE, HEX_SIZE * 2, HEX_SIZE * 2)

  // Banks
  ctx.strokeStyle = 'rgba(119,127,83,.5)'
  ctx.lineWidth = 2
  for (const n of neighborsOf(c, r)) {
    const t = terrainKeyAt(n.c, n.r)
    if (t === 'R' || t === 'bridge' || t === null) continue
    const p = hexToPixel(n.c, n.r)
    const pts = hexPoints(x, y, HEX_SIZE * 0.99)
    const angle = Math.atan2(p.y - y, p.x - x)
    let seg = Math.round(((angle + TAU) % TAU) / (Math.PI / 3)) % 6
    const pairs = [[1, 2], [2, 3], [3, 4], [4, 5], [5, 0], [0, 1]]
    const [ia, ib] = pairs[seg]
    ctx.beginPath()
    ctx.moveTo(pts[ia].x, pts[ia].y)
    ctx.lineTo(pts[ib].x, pts[ib].y)
    ctx.stroke()
  }

  // Surface ripples
  for (let i = 0; i < 5; i++) {
    const py = y - 28 + i * 14 + h2(c, r, i) * 5
    ctx.strokeStyle = `rgba(159,203,199,${0.09 + h2(c, r, i + 40) * 0.08})`
    ctx.lineWidth = 1
    ctx.beginPath()
    ctx.moveTo(x - 32 + h2(c, r, i + 10) * 16, py)
    ctx.quadraticCurveTo(x, py - 4, x + 30, py + 1)
    ctx.stroke()
  }
  ctx.fillStyle = 'rgba(210,232,220,.08)'
  for (let i = 0; i < 7; i++) {
    ctx.fillRect(x - 30 + h2(c, r, i + 70) * 60, y - 25 + h2(c, r, i + 90) * 50, 4 + h2(c, r, i) * 8, 1)
  }

  if (bridge) drawBridge(ctx, x, y, c, r)
}

function drawBridge(ctx, x, y) {
  // A timber deck crossing the river along the east-west road.
  ctx.save()
  ctx.translate(x, y)
  ctx.fillStyle = 'rgba(17,20,13,.35)'
  ctx.fillRect(-44, -13, 92, 34)
  ctx.fillStyle = '#75603a'
  ctx.fillRect(-44, -16, 88, 32)
  ctx.fillStyle = '#8b7246'
  ctx.fillRect(-44, -13, 88, 26)
  // Planks
  ctx.strokeStyle = 'rgba(67,51,27,.8)'
  ctx.lineWidth = 1.1
  for (let i = -40; i <= 40; i += 7) {
    ctx.beginPath()
    ctx.moveTo(i, -13)
    ctx.lineTo(i - 1.5, 13)
    ctx.stroke()
  }
  // Rails
  ctx.fillStyle = 'rgba(53,42,23,.95)'
  ctx.fillRect(-44, -17, 88, 3)
  ctx.fillRect(-44, 14, 88, 3)
  for (let i = -40; i <= 40; i += 18) {
    ctx.fillRect(i, -19, 2.5, 9)
    ctx.fillRect(i, 10, 2.5, 9)
  }
  // Tire tracks
  ctx.strokeStyle = 'rgba(52,43,25,.45)'
  ctx.lineWidth = 2
  ctx.beginPath()
  ctx.moveTo(-40, -5)
  ctx.lineTo(40, -5)
  ctx.moveTo(-40, 5)
  ctx.lineTo(40, 5)
  ctx.stroke()
  ctx.restore()
}

function drawRoad(ctx) {
  const pts = []
  for (let c = 0; c < COLS; c++) pts.push(hexToPixel(c, 4))
  ctx.save()
  ctx.lineCap = 'round'
  ctx.lineJoin = 'round'
  ctx.beginPath()
  ctx.moveTo(pts[0].x - 10, pts[0].y)
  for (let i = 1; i < pts.length; i++) {
    const prev = pts[i - 1]
    const cur = pts[i]
    const mx = (prev.x + cur.x) / 2
    ctx.quadraticCurveTo(prev.x, prev.y + (h2(i, 4, 2) - 0.5) * 2, mx, (prev.y + cur.y) / 2)
    ctx.lineTo(cur.x, cur.y + (h2(i, 4, 3) - 0.5) * 2)
  }
  ctx.strokeStyle = 'rgba(49,41,25,.85)'
  ctx.lineWidth = 25
  ctx.stroke()
  ctx.strokeStyle = '#8b7347'
  ctx.lineWidth = 19
  ctx.stroke()
  ctx.strokeStyle = 'rgba(181,157,105,.45)'
  ctx.lineWidth = 3
  ctx.stroke()
  // Tire ruts
  ctx.strokeStyle = 'rgba(66,53,30,.4)'
  ctx.lineWidth = 1.6
  for (const off of [-5, 5]) {
    ctx.beginPath()
    for (let i = 0; i < pts.length; i++) {
      const p = pts[i]
      if (i === 0) ctx.moveTo(p.x, p.y + off)
      else {
        const prev = pts[i - 1]
        const mx = (prev.x + p.x) / 2
        ctx.quadraticCurveTo(prev.x, prev.y + off, mx, (prev.y + p.y) / 2 + off)
        ctx.lineTo(p.x, p.y + off)
      }
    }
    ctx.stroke()
  }
  ctx.restore()
}

function drawBasePerimeter(ctx) {
  const pairs = [[1, 2], [2, 3], [3, 4], [4, 5], [5, 0], [0, 1]]
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      if (!isBaseCell(c, r)) continue
      const p = hexToPixel(c, r)
      for (const n of neighborsOf(c, r)) {
        if (!isBaseCell(n.c, n.r)) {
          const np = hexToPixel(n.c, n.r)
          const angle = Math.atan2(np.y - p.y, np.x - p.x)
          const seg = Math.round(((angle + TAU) % TAU) / (Math.PI / 3)) % 6
          const [ia, ib] = pairs[seg]
          const pts = hexPoints(p.x, p.y, HEX_SIZE * 0.94)
          const a = pts[ia]
          const b = pts[ib]
          // Leave a gate where the road enters the firebase.
          if (isRoad(c, r) && isRoad(n.c, n.r)) continue
          ctx.strokeStyle = 'rgba(53,47,31,.8)'
          ctx.lineWidth = 7
          ctx.beginPath()
          ctx.moveTo(a.x, a.y)
          ctx.lineTo(b.x, b.y)
          ctx.stroke()
          for (let t = 0.08; t <= 0.92; t += 0.14) {
            const px = a.x + (b.x - a.x) * t
            const py = a.y + (b.y - a.y) * t
            ctx.fillStyle = h2(c, r, Math.round(t * 100)) > 0.5
              ? 'rgba(188,174,126,.95)' : 'rgba(154,140,99,.95)'
            ctx.beginPath()
            ctx.ellipse(px, py, 3.6, 2.5, angle + Math.PI / 2, 0, TAU)
            ctx.fill()
            ctx.strokeStyle = 'rgba(65,57,37,.6)'
            ctx.lineWidth = 0.5
            ctx.stroke()
          }
          // Concertina wire, outside the wall
          const ox = (a.x + b.x) / 2
          const oy = (a.y + b.y) / 2
          const nx = Math.cos(angle) * 5.5
          const ny = Math.sin(angle) * 5.5
          ctx.strokeStyle = 'rgba(62,62,48,.65)'
          ctx.lineWidth = 1
          ctx.beginPath()
          ctx.moveTo(a.x + nx, a.y + ny)
          ctx.lineTo(b.x + nx, b.y + ny)
          ctx.stroke()
          for (let t = 0.1; t <= 0.9; t += 0.16) {
            const px = a.x + (b.x - a.x) * t + nx
            const py = a.y + (b.y - a.y) * t + ny
            ctx.beginPath()
            ctx.moveTo(px - 2, py - 2)
            ctx.lineTo(px + 2, py + 2)
            ctx.moveTo(px + 2, py - 2)
            ctx.lineTo(px - 2, py + 2)
            ctx.stroke()
          }
        }
      }
    }
  }
}

function drawCraters(ctx) {
  for (const crater of CRATERS) {
    const p = hexToPixel(crater.c, crater.r)
    const rr = crater.s
    const g = ctx.createRadialGradient(p.x, p.y, 1, p.x, p.y, rr)
    g.addColorStop(0, 'rgba(27,24,15,.8)')
    g.addColorStop(0.65, 'rgba(48,42,27,.55)')
    g.addColorStop(1, 'rgba(103,88,57,.08)')
    ctx.fillStyle = g
    ctx.beginPath()
    ctx.ellipse(p.x, p.y, rr, rr * 0.68, h2(crater.c, crater.r) * 2, 0, TAU)
    ctx.fill()
    ctx.strokeStyle = 'rgba(167,149,103,.2)'
    ctx.lineWidth = 1.2
    ctx.beginPath()
    ctx.ellipse(p.x, p.y, rr * 0.9, rr * 0.6, h2(crater.c, crater.r) * 2, 0, TAU)
    ctx.stroke()
  }
}

function drawMapLabels(ctx) {
  for (const label of MAP_LABELS) {
    const p = hexToPixel(label.c, label.r)
    ctx.save()
    ctx.translate(p.x, p.y)
    if (label.rotate) ctx.rotate(label.rotate)
    ctx.font = `600 ${label.size}px ${FONT_MONO}`
    ctx.fillStyle = label.color
    ctx.textBaseline = 'middle'
    ctx.shadowColor = 'rgba(5,8,4,.65)'
    ctx.shadowBlur = 4
    drawSpacedText(ctx, label.text, 0, 0, label.spacing)
    ctx.restore()
  }
  // Firebases get a crosshair marker.
  const fp = hexToPixel(2, 4)
  ctx.strokeStyle = 'rgba(211,190,124,.45)'
  ctx.lineWidth = 1
  ctx.beginPath()
  ctx.arc(fp.x, fp.y, 34, 0, TAU)
  ctx.moveTo(fp.x - 42, fp.y)
  ctx.lineTo(fp.x - 37, fp.y)
  ctx.moveTo(fp.x + 37, fp.y)
  ctx.lineTo(fp.x + 42, fp.y)
  ctx.moveTo(fp.x, fp.y - 42)
  ctx.lineTo(fp.x, fp.y - 37)
  ctx.stroke()
}

function drawBorder(ctx) {
  ctx.strokeStyle = 'rgba(208,193,147,.22)'
  ctx.lineWidth = 1
  ctx.strokeRect(7, 7, BOARD_W - 14, BOARD_H - 14)
  ctx.strokeStyle = 'rgba(208,193,147,.12)'
  ctx.strokeRect(11, 11, BOARD_W - 22, BOARD_H - 22)

  // Corner brackets
  ctx.strokeStyle = 'rgba(224,205,150,.55)'
  ctx.lineWidth = 1.6
  const corners = [
    [18, 18, 1, 1], [BOARD_W - 18, 18, -1, 1],
    [18, BOARD_H - 18, 1, -1], [BOARD_W - 18, BOARD_H - 18, -1, -1]
  ]
  for (const [x, y, sx, sy] of corners) {
    ctx.beginPath()
    ctx.moveTo(x, y + sy * 16)
    ctx.lineTo(x, y)
    ctx.lineTo(x + sx * 16, y)
    ctx.stroke()
  }

  // Column coordinates
  ctx.font = `600 9px ${FONT_MONO}`
  ctx.fillStyle = 'rgba(208,193,147,.45)'
  ctx.textAlign = 'center'
  ctx.textBaseline = 'middle'
  for (let c = 0; c < COLS; c++) {
    const top = hexToPixel(c, 0)
    const bottom = hexToPixel(c, ROWS - 1)
    ctx.fillText(colLetter(c), top.x, 20)
    ctx.fillText(colLetter(c), bottom.x, BOARD_H - 20)
  }
  for (let r = 0; r < ROWS; r++) {
    const p = hexToPixel(0, r)
    ctx.fillText(String(r + 1), 20, p.y)
    ctx.fillText(String(r + 1), BOARD_W - 20, p.y)
  }

  // Compass rose
  ctx.save()
  ctx.translate(BOARD_W - 62, BOARD_H - 62)
  ctx.strokeStyle = 'rgba(211,196,150,.42)'
  ctx.fillStyle = 'rgba(211,196,150,.55)'
  ctx.lineWidth = 1
  ctx.beginPath()
  ctx.arc(0, 0, 17, 0, TAU)
  ctx.stroke()
  ctx.beginPath()
  ctx.moveTo(0, -22)
  ctx.lineTo(4, 0)
  ctx.lineTo(0, 6)
  ctx.lineTo(-4, 0)
  ctx.closePath()
  ctx.fill()
  ctx.font = `700 8px ${FONT_MONO}`
  ctx.textAlign = 'center'
  ctx.fillText('N', 0, -26)
  ctx.restore()

  // Scale bar
  ctx.save()
  ctx.translate(26, BOARD_H - 38)
  ctx.strokeStyle = 'rgba(211,196,150,.4)'
  ctx.lineWidth = 1
  ctx.beginPath()
  ctx.moveTo(0, 0)
  ctx.lineTo(90, 0)
  for (let i = 0; i <= 3; i++) {
    ctx.moveTo(i * 30, -3)
    ctx.lineTo(i * 30, 3)
  }
  ctx.stroke()
  ctx.font = `600 8px ${FONT_MONO}`
  ctx.fillStyle = 'rgba(211,196,150,.48)'
  ctx.textAlign = 'left'
  ctx.fillText('0', 0, 12)
  ctx.fillText('250 m', 58, 12)
  ctx.fillText('SHEET 1 · QUANG TRI', 0, -10)
  ctx.restore()
}

function drawGrain(ctx) {
  for (let i = 0; i < 1300; i++) {
    const x = h2(i, 1, 11) * BOARD_W
    const y = h2(i, 2, 12) * BOARD_H
    ctx.fillStyle = i % 3 === 0 ? 'rgba(224,210,166,.035)' : 'rgba(0,0,0,.05)'
    ctx.fillRect(x, y, 1, 1)
  }
  // Faint topo lines in the margin
  ctx.strokeStyle = 'rgba(194,184,142,.05)'
  ctx.lineWidth = 0.8
  for (let i = 0; i < 9; i++) {
    ctx.beginPath()
    ctx.ellipse(BOARD_W * 0.25 + i * 8, BOARD_H * 0.15, 160 + i * 26, 80 + i * 12, 0.3, 0, TAU)
    ctx.stroke()
  }
}

export function buildStaticLayer() {
  const canvas = document.createElement('canvas')
  canvas.width = Math.ceil(BOARD_W * STATIC_SCALE)
  canvas.height = Math.ceil(BOARD_H * STATIC_SCALE)
  const ctx = canvas.getContext('2d')
  ctx.scale(STATIC_SCALE, STATIC_SCALE)

  // Dark margin beneath the map.
  ctx.fillStyle = '#10150d'
  ctx.fillRect(0, 0, BOARD_W, BOARD_H)
  drawGrain(ctx)

  // Hex fills
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      const t = terrainAt(c, r)
      const p = hexToPixel(c, r)
      const shade = h2(c, r, 1)
      ctx.fillStyle = t.color
      hexPath(ctx, p.x, p.y, HEX_SIZE * 1.012)
      ctx.fill()
      if (shade > 0.6) {
        ctx.fillStyle = 'rgba(220,208,160,.028)'
        ctx.fill()
      }
    }
  }

  // Terrain detail, clipped to each hex.
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      const key = terrainKeyAt(c, r)
      const p = hexToPixel(c, r)
      ctx.save()
      clipHex(ctx, p.x, p.y, HEX_SIZE * 1.004)
      if (key === 'J') drawJungle(ctx, p.x, p.y, c, r)
      else if (key === 'P') drawPaddy(ctx, p.x, p.y, c, r)
      else if (key === 'H') drawHill(ctx, p.x, p.y, c, r)
      else if (key === 'V') drawVillage(ctx, p.x, p.y, c, r)
      else if (key === 'B') drawBaseGround(ctx, p.x, p.y, c, r)
      else if (key === 'G') drawGrass(ctx, p.x, p.y, c, r)
      else if (key === 'R') drawWater(ctx, p.x, p.y, c, r)
      else if (key === 'bridge') drawWater(ctx, p.x, p.y, c, r, true)
      ctx.restore()
    }
  }

  drawRoad(ctx)
  // The bridge deck sits above the road for a convincing crossing.
  const bridgePixel = hexToPixel(BRIDGE.c, BRIDGE.r)
  ctx.save()
  clipHex(ctx, bridgePixel.x, bridgePixel.y, HEX_SIZE * 1.004)
  drawBridge(ctx, bridgePixel.x, bridgePixel.y)
  ctx.restore()

  drawBasePerimeter(ctx)
  drawCraters(ctx)

  // Soft hex lattice
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      const p = hexToPixel(c, r)
      hexPath(ctx, p.x, p.y, HEX_SIZE)
      ctx.strokeStyle = 'rgba(8,12,7,.17)'
      ctx.lineWidth = 1
      ctx.stroke()
    }
  }

  // Vignette along the map edge
  const vg = ctx.createRadialGradient(BOARD_W / 2, BOARD_H / 2, BOARD_H * 0.32, BOARD_W / 2, BOARD_H / 2, BOARD_W * 0.72)
  vg.addColorStop(0, 'rgba(0,0,0,0)')
  vg.addColorStop(1, 'rgba(2,5,2,.42)')
  ctx.fillStyle = vg
  ctx.fillRect(0, 0, BOARD_W, BOARD_H)

  drawMapLabels(ctx)
  drawBorder(ctx)

  return canvas
}

export { STATIC_SCALE }

import {
  COLS, ROWS, HEX_SIZE, HEX_W, BOARD_W, BOARD_H, TERRAIN,
  terrainAt, terrainKeyAt, MAP_LABELS, BRIDGE
} from './data.js'
import { hexToPixel, hexDistance, neighborsOf, keyOf } from './engine.js'
import { buildStaticLayer } from './render-terrain.js'
import {
  TAU, FONT_MONO, FONT_DISPLAY, clamp, easeOutCubic, easeInOut, h2,
  hexPath, roundedRect, drawUnitIcon
} from './render-utils.js'
import { drawEffect } from './render-effects.js'

const US_RING = 'rgba(174,211,146,.95)'
const NVA_RING = 'rgba(226,120,96,.95)'
const GOLD = 'rgba(226,193,112,.95)'

function hexCenter(c, r) {
  return hexToPixel(c, r)
}

function inCell(a, b) {
  return a && b && a.c === b.c && a.r === b.r
}

export class Renderer {
  constructor(canvas, game, ui) {
    this.canvas = canvas
    this.ctx = canvas.getContext('2d')
    this.game = game
    this.ui = ui
    this.staticLayer = buildStaticLayer()
    this.view = { scale: 1, ox: 0, oy: 0, w: 0, h: 0, dpr: 1 }
    this.effects = []
    this.shake = null
    this.reducedMotion = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches || false
    this.ro = new ResizeObserver(() => this.resize())
    this.ro.observe(canvas.parentElement || canvas)
    window.addEventListener('resize', () => this.resize())
    this.resize()
    this.loop = this.loop.bind(this)
    requestAnimationFrame(this.loop)
  }

  setGame(game) {
    this.game = game
    this.effects = []
    this.shake = null
  }

  resize() {
    const parent = this.canvas.parentElement || this.canvas
    const rect = parent.getBoundingClientRect()
    const w = Math.max(1, rect.width)
    const h = Math.max(1, rect.height)
    const dpr = Math.min(2, window.devicePixelRatio || 1)
    this.canvas.width = Math.round(w * dpr)
    this.canvas.height = Math.round(h * dpr)
    this.canvas.style.width = `${w}px`
    this.canvas.style.height = `${h}px`
    const pad = w < 560 ? 4 : 8
    const scale = Math.min((w - pad * 2) / BOARD_W, (h - pad * 2) / BOARD_H)
    this.view = {
      w, h, dpr, scale,
      ox: (w - BOARD_W * scale) / 2,
      oy: (h - BOARD_H * scale) / 2
    }
  }

  screenToBoard(clientX, clientY) {
    const rect = this.canvas.getBoundingClientRect()
    const x = (clientX - rect.left - this.view.ox) / this.view.scale
    const y = (clientY - rect.top - this.view.oy) / this.view.scale
    return { x, y }
  }

  pickHex(clientX, clientY) {
    const p = this.screenToBoard(clientX, clientY)
    if (p.x < 0 || p.y < 0 || p.x > BOARD_W || p.y > BOARD_H) return null
    let best = null
    let bestDist = Infinity
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) {
        const center = hexCenter(c, r)
        const d = (center.x - p.x) ** 2 + (center.y - p.y) ** 2
        if (d < bestDist) {
          bestDist = d
          best = { c, r }
        }
      }
    }
    if (!best || bestDist > (HEX_SIZE * 1.12) ** 2) return null
    return best
  }

  pickUnit(clientX, clientY) {
    const cell = this.pickHex(clientX, clientY)
    if (!cell) return null
    return this.game.occupied(cell.c, cell.r)
  }

  addEffect(effect) {
    this.effects.push(effect)
    if (this.effects.length > 160) this.effects.shift()
  }

  addShake(mag = 4, dur = 280) {
    const now = Date.now()
    if (this.shake) {
      const remaining = this.shake.dur - (now - this.shake.start)
      if (remaining > dur * 0.5 && this.shake.mag >= mag) return
    }
    this.shake = { start: now, dur, mag }
  }

  handleEvent(event) {
    if (!event) return
    const now = Date.now()
    switch (event.type) {
      case 'attack': {
        const a = hexCenter(event.from.c, event.from.r)
        const b = hexCenter(event.to.c, event.to.r)
        const heavy = /90mm|76\.2|82mm|RPG|mortar/i.test(event.weapon || '')
        const killedTarget = event.killed
        if (event.indirect) {
          this.addEffect({ type: 'arc', x1: a.x, y1: a.y, x2: b.x, y2: b.y, start: now, dur: 500, side: event.attackerSide })
          this.addEffect({ type: 'explosion', x: b.x, y: b.y, start: now + 470, dur: 780, size: heavy ? 31 : 23, seed: h2(event.to.c, event.to.r) * TAU })
        } else {
          this.addEffect({ type: 'tracer', x1: a.x, y1: a.y, x2: b.x, y2: b.y, start: now, dur: 340, side: event.attackerSide, heavy })
          this.addEffect({ type: 'explosion', x: b.x, y: b.y, start: now + 180, dur: 620, size: heavy ? 28 : 18, seed: h2(event.to.c, event.to.r) * TAU })
        }
        if (event.attackerSide === 'nva') this.addShake(heavy ? 7 : 3.2)
        this.addEffect({
          type: 'text',
          x: b.x,
          y: b.y - 18,
          text: `-${event.damage}`,
          start: now + 240,
          dur: 900,
          color: event.defenderSide === 'us' ? '#ff9b83' : '#f4dc9c',
          size: heavy ? 17 : 14
        })
        if (event.suppressed) {
          this.addEffect({
            type: 'text', x: b.x, y: b.y - 32, text: 'PINNED', start: now + 330,
            dur: 900, color: '#e9b36b', size: 10
          })
        }
        if (killedTarget) {
          this.addEffect({
            type: 'text', x: b.x, y: b.y - 42, text: 'DESTROYED', start: now + 360,
            dur: 1100, color: event.defenderSide === 'us' ? '#ff8b74' : '#dfc077', size: 10
          })
        }
        if (event.splash?.length) {
          for (const s of event.splash) {
            const target = this.game.getUnit(s.unitId)
            if (!target) continue
            const p = hexCenter(target.c, target.r)
            this.addEffect({ type: 'explosion', x: p.x, y: p.y, start: now + 230, dur: 520, size: 16, seed: h2(target.c, target.r) * TAU })
            this.addEffect({ type: 'text', x: p.x, y: p.y - 16, text: `-${s.damage}`, start: now + 300, dur: 780, color: '#f4dc9c', size: 11 })
          }
        }
        break
      }
      case 'support': {
        const p = hexCenter(event.c, event.r)
        if (event.kind === 'artillery') {
          this.addShake(11, 560)
          this.addEffect({ type: 'ring', x: p.x, y: p.y, start: now, dur: 700, radius: 52, color: 'rgba(255,214,130,.7)', width: 2 })
          this.addEffect({ type: 'explosion', x: p.x, y: p.y, start: now, dur: 1100, size: 48, seed: 1.1 })
          const around = neighborsOf(event.c, event.r)
          for (let i = 0; i < around.length; i += 2) {
            const q = hexCenter(around[i].c, around[i].r)
            this.addEffect({ type: 'explosion', x: q.x, y: q.y, start: now + 120 + i * 55, dur: 700, size: 23, seed: i * 1.7 })
          }
          this.addEffect({ type: 'text', x: p.x, y: p.y - 42, text: '105mm', start: now + 60, dur: 1200, color: '#ffe6a8', size: 13 })
        } else if (event.kind === 'huey') {
          this.addShake(7, 650)
          this.addEffect({ type: 'huey', x: p.x, y: p.y, start: now, dur: 1600 })
          this.addEffect({ type: 'explosion', x: p.x, y: p.y, start: now + 450, dur: 800, size: 30, seed: 0.4 })
          const around = neighborsOf(event.c, event.r)
          for (let i = 1; i < around.length; i += 3) {
            const q = hexCenter(around[i].c, around[i].r)
            this.addEffect({ type: 'explosion', x: q.x, y: q.y, start: now + 520 + i * 30, dur: 560, size: 18, seed: i })
          }
          this.addEffect({ type: 'text', x: p.x, y: p.y - 48, text: 'GUNSHIP', start: now + 380, dur: 1100, color: '#d9f0bd', size: 11 })
        } else if (event.kind === 'dustoff') {
          this.addEffect({ type: 'heal', x: p.x, y: p.y, start: now, dur: 1200 })
          if (event.heal > 0) {
            this.addEffect({ type: 'text', x: p.x, y: p.y - 24, text: `+${event.heal}`, start: now, dur: 1200, color: '#9ce7b4', size: 14 })
          }
        }
        break
      }
      case 'death': {
        const p = hexCenter(event.c, event.r)
        this.addEffect({ type: 'explosion', x: p.x, y: p.y, start: now, dur: 800, size: event.objective ? 50 : 24, seed: h2(event.c, event.r) * TAU })
        if (event.objective) this.addShake(13, 800)
        break
      }
      case 'move': {
        const p = hexCenter(event.to.c, event.to.r)
        this.addEffect({ type: 'dust', x: p.x, y: p.y + 8, start: now + 80, dur: 520, seed: h2(event.to.c, event.to.r) * TAU })
        break
      }
      case 'spawn': {
        const p = hexCenter(event.c, event.r)
        this.addEffect({ type: 'ring', x: p.x, y: p.y, start: now, dur: 900, radius: 30, color: 'rgba(230,130,104,.8)', width: 2 })
        break
      }
      case 'gameOver': {
        if (event.result === 'defeat') {
          const bunker = this.game.getBunker()
          if (bunker) {
            const p = hexCenter(bunker.c, bunker.r)
            this.addEffect({ type: 'explosion', x: p.x, y: p.y, start: now + 300, dur: 1600, size: 60, seed: 2.3 })
          }
          this.addShake(10, 900)
        }
        break
      }
      default:
        break
    }
  }

  loop() {
    const now = Date.now()
    this.draw(now)
    requestAnimationFrame(this.loop)
  }

  draw(now) {
    const ctx = this.ctx
    const { w, h, dpr, scale, ox, oy } = this.view
    if (!w || !h) return
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
    ctx.clearRect(0, 0, w, h)

    // Canvas backdrop / map-table texture
    const bg = ctx.createRadialGradient(w * 0.5, h * 0.35, 10, w * 0.5, h * 0.5, Math.max(w, h) * 0.78)
    bg.addColorStop(0, '#1c2418')
    bg.addColorStop(0.55, '#11170f')
    bg.addColorStop(1, '#080b07')
    ctx.fillStyle = bg
    ctx.fillRect(0, 0, w, h)
    ctx.strokeStyle = 'rgba(190,180,140,.035)'
    ctx.lineWidth = 1
    for (let x = 0; x < w; x += 46) {
      ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, h); ctx.stroke()
    }
    for (let y = 0; y < h; y += 46) {
      ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(w, y); ctx.stroke()
    }

    let sx = 0
    let sy = 0
    if (this.shake) {
      const sp = (now - this.shake.start) / this.shake.dur
      if (sp >= 1) this.shake = null
      else {
        const mag = this.shake.mag * (1 - sp)
        sx = Math.sin(now * 0.11) * mag
        sy = Math.cos(now * 0.14) * mag * 0.7
      }
    }

    // Board shadow
    ctx.save()
    ctx.translate(ox + sx, oy + sy)
    ctx.scale(scale, scale)
    ctx.shadowColor = 'rgba(0,0,0,.55)'
    ctx.shadowBlur = 18
    ctx.fillStyle = '#0d120c'
    ctx.fillRect(-6, -6, BOARD_W + 12, BOARD_H + 12)
    ctx.shadowBlur = 0
    ctx.drawImage(this.staticLayer, 0, 0, BOARD_W, BOARD_H)

    this.drawWater(ctx, now)
    if (!this.reducedMotion) this.drawMist(ctx, now)
    this.drawSmoke(ctx, now)
    this.drawObjectiveRing(ctx, now)
    this.drawOverlaysBelow(ctx, now)
    this.drawUnits(ctx, now)
    this.drawOverlaysAbove(ctx, now)
    this.drawEffects(ctx, now)
    if (!this.reducedMotion) this.drawRain(ctx, now)
    ctx.restore()
  }

  drawWater(ctx, now) {
    const t = this.reducedMotion ? 0 : now * 0.00065
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) {
        const key = terrainKeyAt(c, r)
        if (key !== 'R') continue
        const p = hexCenter(c, r)
        ctx.save()
        ctx.beginPath()
        hexPath(ctx, p.x, p.y, HEX_SIZE * 1.002)
        ctx.clip()
        for (let i = 0; i < 2; i++) {
          const off = Math.sin(t + h2(c, r, i) * TAU) * 7
          const y = p.y - 20 + i * 22 + off
          ctx.strokeStyle = `rgba(182,222,210,${0.075 + 0.03 * Math.sin(t * 1.3 + i)})`
          ctx.lineWidth = 1.4
          ctx.beginPath()
          ctx.moveTo(p.x - 38, y)
          ctx.quadraticCurveTo(p.x - 4 + off, y - 4, p.x + 20, y + 1)
          ctx.quadraticCurveTo(p.x + 33, y + 3, p.x + 40, y)
          ctx.stroke()
        }
        ctx.fillStyle = 'rgba(220,240,226,.08)'
        const gx = p.x - 24 + ((now * 0.008 + h2(c, r, 4) * 100) % 52)
        ctx.fillRect(gx, p.y - 10 + Math.sin(t + h2(c, r, 7) * 8) * 10, 6, 1.2)
        ctx.restore()
      }
    }
  }

  drawMist(ctx, now) {
    ctx.save()
    ctx.beginPath()
    ctx.rect(0, 0, BOARD_W, BOARD_H)
    ctx.clip()
    for (let i = 0; i < 4; i++) {
      const x = ((now * 0.005 + i * 280 + h2(i, 1) * 130) % (BOARD_W + 300)) - 150
      const y = BOARD_H * (0.18 + i * 0.18)
      const g = ctx.createRadialGradient(x, y, 4, x, y, 180)
      g.addColorStop(0, 'rgba(180,190,166,.055)')
      g.addColorStop(1, 'rgba(180,190,166,0)')
      ctx.fillStyle = g
      ctx.beginPath()
      ctx.ellipse(x, y, 220, 48, 0.04, 0, TAU)
      ctx.fill()
    }
    ctx.restore()
  }

  drawSmoke(ctx, now) {
    const bunker = this.game.getBunker()
    if (bunker && bunker.alive) {
      const p = hexCenter(bunker.c, bunker.r)
      this.plume(ctx, p.x - 4, p.y - 18, now, 1)
    }
    const p2 = hexCenter(1, 3)
    this.plume(ctx, p2.x + 8, p2.y - 12, now + 800, 2, 0.72)
    if (this.game.phase === 'over' && this.game.result === 'defeat') {
      const p = hexCenter(this.game.getBunker()?.c || 2, this.game.getBunker()?.r || 4)
      this.plume(ctx, p.x, p.y - 12, now + 300, 3, 1.3)
    }
  }

  plume(ctx, x, y, now, seed, scale = 1) {
    const t = this.reducedMotion ? 0 : now * 0.00012
    ctx.save()
    for (let i = 0; i < 6; i++) {
      const phase = (t + i / 6 + seed * 0.17) % 1
      const px = x + Math.sin(phase * 5 + seed + i) * 8 + phase * 18
      const py = y - phase * 58 * scale
      const rr = (3 + phase * 8) * scale
      ctx.fillStyle = `rgba(73,73,61,${(1 - phase) * 0.2})`
      ctx.beginPath()
      ctx.arc(px, py, rr, 0, TAU)
      ctx.fill()
    }
    ctx.restore()
  }

  drawRain(ctx, now) {
    ctx.save()
    ctx.beginPath()
    ctx.rect(0, 0, BOARD_W, BOARD_H)
    ctx.clip()
    ctx.strokeStyle = 'rgba(190,206,184,.06)'
    ctx.lineWidth = 0.8
    for (let i = 0; i < 74; i++) {
      const speed = 0.06 + h2(i, 8) * 0.08
      const x = (h2(i, 2) * BOARD_W + now * speed) % BOARD_W
      const y = (h2(i, 3) * BOARD_H + now * speed * 1.4) % BOARD_H
      ctx.beginPath()
      ctx.moveTo(x, y)
      ctx.lineTo(x - 3, y + 9)
      ctx.stroke()
    }
    ctx.restore()
  }

  drawObjectiveRing(ctx, now) {
    const bunker = this.game.getBunker()
    if (!bunker || !bunker.alive) return
    const p = hexCenter(bunker.c, bunker.r)
    const pulse = 0.5 + Math.sin(now * 0.003) * 0.2
    ctx.save()
    ctx.strokeStyle = `rgba(225,193,110,${pulse})`
    ctx.lineWidth = 1.4
    ctx.setLineDash([4, 5])
    ctx.lineDashOffset = -now * 0.02
    ctx.beginPath()
    ctx.arc(p.x, p.y, 34, 0, TAU)
    ctx.stroke()
    ctx.restore()
  }

  drawOverlaysBelow(ctx, now) {
    const game = this.game
    const selected = game.getUnit(this.ui.selectedId)
    const hover = this.ui.hover
    const phase = game.phase

    if (selected && selected.side === 'us' && selected.alive && phase === 'player') {
      if (!selected.moved && !selected.attacked && !selected.cannotAct) {
        const { costs } = game.reachableMap(selected)
        for (const k of costs.keys()) {
          const [c, r] = k.split(',').map(Number)
          if (c === selected.c && r === selected.r) continue
          const p = hexCenter(c, r)
          ctx.fillStyle = 'rgba(159,205,144,.13)'
          hexPath(ctx, p.x, p.y, HEX_SIZE * 0.94)
          ctx.fill()
          ctx.strokeStyle = 'rgba(177,219,157,.28)'
          ctx.lineWidth = 1
          ctx.stroke()
        }
        if (hover && costs.has(keyOf(hover.c, hover.r))) {
          const path = game.pathFromMap(selected, hover.c, hover.r, game.reachableMap(selected).prev)
          if (path && path.length > 1) this.drawPath(ctx, path, now, 'rgba(222,205,142,.9)')
        }
      }
      if (!selected.attacked && !selected.cannotAct && selected.range > 0) {
        for (let r = 0; r < ROWS; r++) {
          for (let c = 0; c < COLS; c++) {
            const d = hexDistance({ c, r }, selected)
            if (d > selected.range || d < (selected.minRange || 0) || d === 0) continue
            const p = hexCenter(c, r)
            ctx.strokeStyle = 'rgba(220,108,84,.10)'
            ctx.lineWidth = 1
            hexPath(ctx, p.x, p.y, HEX_SIZE * 0.91)
            ctx.stroke()
          }
        }
        for (const enemy of game.enemyUnits()) {
          if (!game.inAttackRange(selected, enemy)) continue
          const p = hexCenter(enemy.c, enemy.r)
          const pulse = 0.5 + Math.sin(now * 0.006) * 0.15
          ctx.fillStyle = `rgba(220,91,68,${0.12 + pulse * 0.06})`
          hexPath(ctx, p.x, p.y, HEX_SIZE * 0.98)
          ctx.fill()
          ctx.strokeStyle = 'rgba(239,125,98,.55)'
          ctx.lineWidth = 1.6
          ctx.stroke()
        }
      }
    }

    if (hover) {
      const p = hexCenter(hover.c, hover.r)
      const unit = game.occupied(hover.c, hover.r)
      if (!this.ui.mode) {
        ctx.strokeStyle = unit ? 'rgba(235,222,176,.72)' : 'rgba(220,209,164,.28)'
        ctx.lineWidth = unit ? 1.8 : 1
        hexPath(ctx, p.x, p.y, HEX_SIZE * 0.97)
        ctx.stroke()
      }
    }

    if (this.ui.mode && hover) this.drawSupportRadius(ctx, hover.c, hover.r, now)
  }

  drawSupportRadius(ctx, c, r, now) {
    const kind = this.ui.mode.kind
    const isDustoff = kind === 'dustoff'
    const cells = isDustoff ? [{ c, r }] : [{ c, r }, ...neighborsOf(c, r)]
    for (const cell of cells) {
      const p = hexCenter(cell.c, cell.r)
      const color = isDustoff ? 'rgba(128,220,158,' : kind === 'artillery' ? 'rgba(237,174,86,' : 'rgba(172,224,154,'
      ctx.fillStyle = color + '0.11)'
      hexPath(ctx, p.x, p.y, HEX_SIZE * 0.96)
      ctx.fill()
      ctx.strokeStyle = color + '0.5)'
      ctx.lineWidth = 1.3
      ctx.stroke()
    }
    const p = hexCenter(c, r)
    const pulse = 0.65 + Math.sin(now * 0.008) * 0.2
    ctx.save()
    ctx.strokeStyle = `rgba(245,215,142,${pulse})`
    ctx.lineWidth = 1.2
    ctx.setLineDash([4, 4])
    ctx.beginPath()
    ctx.arc(p.x, p.y, 16, 0, TAU)
    ctx.stroke()
    ctx.setLineDash([])
    ctx.beginPath()
    ctx.moveTo(p.x - 9, p.y); ctx.lineTo(p.x + 9, p.y)
    ctx.moveTo(p.x, p.y - 9); ctx.lineTo(p.x, p.y + 9)
    ctx.stroke()
    ctx.restore()
  }

  drawPath(ctx, path, now, color) {
    ctx.save()
    ctx.strokeStyle = color
    ctx.lineWidth = 1.8
    ctx.setLineDash([5, 4])
    ctx.lineDashOffset = -now * 0.02
    ctx.beginPath()
    const first = hexCenter(path[0].c, path[0].r)
    ctx.moveTo(first.x, first.y)
    for (let i = 1; i < path.length; i++) {
      const p = hexCenter(path[i].c, path[i].r)
      ctx.lineTo(p.x, p.y)
    }
    ctx.stroke()
    const last = hexCenter(path[path.length - 1].c, path[path.length - 1].r)
    const prev = hexCenter(path[path.length - 2].c, path[path.length - 2].r)
    const a = Math.atan2(last.y - prev.y, last.x - prev.x)
    ctx.setLineDash([])
    ctx.fillStyle = color
    ctx.beginPath()
    ctx.moveTo(last.x, last.y)
    ctx.lineTo(last.x - Math.cos(a - 0.5) * 9, last.y - Math.sin(a - 0.5) * 9)
    ctx.lineTo(last.x - Math.cos(a + 0.5) * 9, last.y - Math.sin(a + 0.5) * 9)
    ctx.closePath()
    ctx.fill()
    ctx.restore()
  }

  renderPos(unit, now) {
    const target = hexCenter(unit.c, unit.r)
    const lm = unit.lastMove
    if (!lm || now - lm.start > lm.duration || lm.duration <= 0) return target
    const path = lm.path.map(p => hexCenter(p.c, p.r))
    if (path.length < 2) return target
    const lengths = []
    let total = 0
    for (let i = 1; i < path.length; i++) {
      const d = Math.hypot(path[i].x - path[i - 1].x, path[i].y - path[i - 1].y)
      lengths.push(d)
      total += d
    }
    const p = easeInOut((now - lm.start) / lm.duration)
    let remaining = total * p
    for (let i = 0; i < lengths.length; i++) {
      if (remaining <= lengths[i]) {
        const t = lengths[i] ? remaining / lengths[i] : 0
        return {
          x: path[i].x + (path[i + 1].x - path[i].x) * t,
          y: path[i].y + (path[i + 1].y - path[i].y) * t
        }
      }
      remaining -= lengths[i]
    }
    return path[path.length - 1]
  }

  drawUnits(ctx, now) {
    const units = this.game.aliveUnits()
      .map(u => ({ u, p: this.renderPos(u, now) }))
      .sort((a, b) => a.p.y - b.p.y)
    for (const { u, p } of units) this.drawUnit(ctx, u, p.x, p.y, now)
  }

  drawUnit(ctx, unit, x, y, now) {
    const selected = this.ui.selectedId === unit.id
    const hovered = this.ui.hover && this.ui.hover.c === unit.c && this.ui.hover.r === unit.r
    const active = this.game.activeEnemyId === unit.id
    const r = unit.objective ? 27 : unit.vehicle ? 22 : 19.5
    const sideColor = unit.side === 'us' ? US_RING : NVA_RING
    const age = now - (unit.spawnedAt || 0)
    const spawnPulse = age >= 0 && age < 720
    const pulse = 0.5 + Math.sin(now * 0.006 + (unit.id.length || 1)) * 0.5

    ctx.save()
    ctx.translate(x, y)
    if (spawnPulse) {
      const t = clamp(age / 720, 0, 1)
      ctx.globalAlpha = t
      const s = 0.72 + easeOutCubic(t) * 0.28
      ctx.scale(s, s)
      ctx.strokeStyle = `rgba(231,137,104,${(1 - t) * 0.8})`
      ctx.lineWidth = 2
      ctx.beginPath()
      ctx.arc(0, 0, r + 10 + t * 22, 0, TAU)
      ctx.stroke()
    }

    // Ground shadow
    ctx.fillStyle = 'rgba(4,7,4,.38)'
    ctx.beginPath()
    ctx.ellipse(0, r * 0.75, r * 0.9, r * 0.34, 0, 0, TAU)
    ctx.fill()

    if (selected) {
      ctx.save()
      ctx.rotate(now * 0.0006)
      ctx.strokeStyle = GOLD
      ctx.lineWidth = 1.7
      ctx.setLineDash([5, 5])
      ctx.beginPath()
      ctx.arc(0, 0, r + 7, 0, TAU)
      ctx.stroke()
      ctx.restore()
    }
    if (active) {
      ctx.strokeStyle = `rgba(231,118,91,${0.55 + pulse * 0.35})`
      ctx.lineWidth = 2
      ctx.beginPath()
      ctx.arc(0, 0, r + 5, 0, TAU)
      ctx.stroke()
    }
    if (hovered && !selected) {
      ctx.strokeStyle = 'rgba(231,219,174,.7)'
      ctx.lineWidth = 1.2
      ctx.beginPath()
      ctx.arc(0, 0, r + 3, 0, TAU)
      ctx.stroke()
    }

    // Token plate
    const grad = ctx.createRadialGradient(-r * 0.28, -r * 0.34, 1, 0, 0, r * 1.16)
    if (unit.side === 'us') {
      grad.addColorStop(0, '#5c6c49')
      grad.addColorStop(0.62, '#33412b')
      grad.addColorStop(1, '#1b2418')
    } else {
      grad.addColorStop(0, '#6f4438')
      grad.addColorStop(0.62, '#42271f')
      grad.addColorStop(1, '#221510')
    }
    ctx.fillStyle = grad
    ctx.beginPath()
    ctx.arc(0, 0, r, 0, TAU)
    ctx.fill()
    ctx.strokeStyle = sideColor
    ctx.lineWidth = unit.objective ? 2.2 : 1.6
    ctx.stroke()
    ctx.strokeStyle = unit.side === 'us' ? 'rgba(110,138,88,.7)' : 'rgba(140,70,54,.7)'
    ctx.lineWidth = 1
    ctx.beginPath()
    ctx.arc(0, 0, r - 3.2, 0, TAU)
    ctx.stroke()

    // Faction mark
    if (unit.side === 'us') {
      ctx.strokeStyle = 'rgba(199,220,168,.7)'
      ctx.lineWidth = 1.1
      ctx.beginPath()
      ctx.arc(0, 0, r - 1.4, -0.7, 0.7)
      ctx.stroke()
    } else {
      ctx.fillStyle = 'rgba(233,147,119,.8)'
      ctx.beginPath()
      const starR = 3
      for (let i = 0; i < 10; i++) {
        const a = -Math.PI / 2 + i * Math.PI / 5
        const rr = i % 2 === 0 ? starR : starR * 0.42
        const px = Math.cos(a) * rr
        const py = Math.sin(a) * rr + r * 0.7
        if (i === 0) ctx.moveTo(px, py)
        else ctx.lineTo(px, py)
      }
      ctx.closePath()
      ctx.fill()
    }

    drawUnitIcon(ctx, unit, r * 0.88)

    // Suppression marker
    if (unit.suppressed) {
      ctx.save()
      ctx.translate(r * 0.75, -r * 0.75)
      ctx.fillStyle = '#e9ad63'
      ctx.beginPath()
      ctx.moveTo(0, -5)
      ctx.lineTo(5, 4)
      ctx.lineTo(-5, 4)
      ctx.closePath()
      ctx.fill()
      ctx.fillStyle = '#20170c'
      ctx.font = `700 6px ${FONT_MONO}`
      ctx.textAlign = 'center'
      ctx.textBaseline = 'middle'
      ctx.fillText('!', 0, 1.5)
      ctx.restore()
    }

    // HP bar
    const barW = r * 1.85
    const by = r + 6
    ctx.fillStyle = 'rgba(8,11,7,.8)'
    roundedRect(ctx, -barW / 2, by, barW, 4.2, 1.5)
    ctx.fill()
    const frac = unit.hp / unit.maxHp
    ctx.fillStyle = frac > 0.6 ? '#8cbf73' : frac > 0.3 ? '#d1a54f' : '#cf644e'
    roundedRect(ctx, -barW / 2 + 0.6, by + 0.6, (barW - 1.2) * frac, 3, 1)
    ctx.fill()
    ctx.strokeStyle = 'rgba(235,225,188,.25)'
    ctx.lineWidth = 0.5
    roundedRect(ctx, -barW / 2, by, barW, 4.2, 1.5)
    ctx.stroke()

    // Name tag
    if (this.view.scale > 0.56) {
      ctx.font = `700 7.8px ${FONT_MONO}`
      ctx.textAlign = 'center'
      ctx.textBaseline = 'middle'
      const label = unit.label
      const tw = ctx.measureText(label).width
      ctx.fillStyle = 'rgba(11,15,9,.72)'
      roundedRect(ctx, -tw / 2 - 3.5, -r - 16, tw + 7, 11, 2.5)
      ctx.fill()
      ctx.fillStyle = unit.objective ? '#e5c67f' : unit.side === 'us' ? '#d4ddbd' : '#e5b9a8'
      ctx.fillText(label, 0, -r - 10.3)
    }

    if (unit.objective) {
      // Pennant above the command bunker
      const flagY = -r - 30
      ctx.strokeStyle = 'rgba(226,205,151,.8)'
      ctx.lineWidth = 1
      ctx.beginPath()
      ctx.moveTo(-1, flagY + 12)
      ctx.lineTo(-1, flagY - 3)
      ctx.stroke()
      ctx.fillStyle = 'rgba(204,119,76,.95)'
      ctx.beginPath()
      ctx.moveTo(-1, flagY - 3)
      ctx.lineTo(13, flagY + 1)
      ctx.lineTo(-1, flagY + 5)
      ctx.closePath()
      ctx.fill()
    }

    ctx.restore()
  }

  drawOverlaysAbove(ctx, now) {
    const game = this.game
    const selected = game.getUnit(this.ui.selectedId)
    const hover = this.ui.hover

    if (selected && hover && game.phase === 'player') {
      const target = game.occupied(hover.c, hover.r)
      if (target && target.side === 'nva' && game.inAttackRange(selected, target) && !selected.attacked) {
        const a = hexCenter(selected.c, selected.r)
        const b = hexCenter(target.c, target.r)
        ctx.save()
        ctx.strokeStyle = 'rgba(238,133,105,.8)'
        ctx.lineWidth = 1.3
        ctx.setLineDash([3, 5])
        ctx.lineDashOffset = -now * 0.03
        ctx.beginPath()
        ctx.moveTo(a.x, a.y)
        ctx.lineTo(b.x, b.y)
        ctx.stroke()
        ctx.setLineDash([])
        const pulse = 0.55 + Math.sin(now * 0.009) * 0.2
        ctx.strokeStyle = `rgba(244,151,116,${pulse})`
        ctx.lineWidth = 2
        ctx.beginPath()
        ctx.arc(b.x, b.y, 26, 0, TAU)
        ctx.stroke()
        ctx.restore()
      }
    }

    if (this.ui.mode && hover) {
      const preview = game.previewSupport(this.ui.mode.kind, hover.c, hover.r)
      for (const hit of preview) {
        const u = game.getUnit(hit.unitId)
        if (!u) continue
        const p = hexCenter(u.c, u.r)
        let text, color
        if (this.ui.mode.kind === 'dustoff') {
          text = hit.heal > 0 ? `+${hit.heal}` : 'FULL'
          color = hit.heal > 0 ? '#9ce7b4' : '#c8d3ac'
        } else if (hit.friendly) {
          text = `-${hit.damage}`
          color = '#f0b466'
        } else {
          text = `-${hit.damage}`
          color = hit.killed ? '#ffd27c' : '#f0d39a'
        }
        this.badge(ctx, p.x, p.y - 36, text, color)
        if (hit.friendly && this.ui.mode.kind === 'artillery') {
          this.badge(ctx, p.x, p.y - 49, 'DANGER', '#f0a45c')
        }
      }
      if (this.ui.mode.kind === 'dustoff') {
        for (const u of game.playerCombatUnits()) {
          if (u.hp >= u.maxHp && !u.suppressed) continue
          const p = hexCenter(u.c, u.r)
          const pulse = 0.5 + Math.sin(now * 0.006) * 0.25
          ctx.strokeStyle = `rgba(132,222,160,${pulse})`
          ctx.lineWidth = 1.6
          ctx.beginPath()
          ctx.arc(p.x, p.y, 28, 0, TAU)
          ctx.stroke()
        }
      }
    }

    if (selected && selected.side === 'us' && selected.alive) {
      const p = hexCenter(selected.c, selected.r)
      ctx.save()
      ctx.strokeStyle = 'rgba(236,213,146,.6)'
      ctx.lineWidth = 1
      ctx.beginPath()
      ctx.moveTo(p.x - 30, p.y - 30)
      ctx.lineTo(p.x - 30, p.y - 25)
      ctx.moveTo(p.x - 30, p.y - 30)
      ctx.lineTo(p.x - 25, p.y - 30)
      ctx.moveTo(p.x + 30, p.y - 30)
      ctx.lineTo(p.x + 30, p.y - 25)
      ctx.moveTo(p.x + 30, p.y - 30)
      ctx.lineTo(p.x + 25, p.y - 30)
      ctx.restore()
    }
  }

  badge(ctx, x, y, text, color) {
    ctx.save()
    ctx.font = `700 10px ${FONT_MONO}`
    ctx.textAlign = 'center'
    ctx.textBaseline = 'middle'
    const w = ctx.measureText(text).width + 8
    ctx.fillStyle = 'rgba(10,14,9,.86)'
    roundedRect(ctx, x - w / 2, y - 7, w, 14, 3)
    ctx.fill()
    ctx.strokeStyle = 'rgba(236,215,150,.35)'
    ctx.lineWidth = 0.8
    ctx.stroke()
    ctx.fillStyle = color
    ctx.fillText(text, x, y + 0.5)
    ctx.restore()
  }

  drawEffects(ctx, now) {
    this.effects = this.effects.filter(e => now - e.start < e.dur)
    for (const effect of this.effects) {
      if (now >= effect.start) drawEffect(ctx, effect, now)
    }
  }
}

// Procedural Web Audio — no external assets, unlocked on the first user gesture.

export class AudioSystem {
  constructor({ muted = false } = {}) {
    this.ctx = null
    this.master = null
    this.ambient = null
    this.muted = muted
    this.ready = false
  }

  async unlock() {
    if (this.ready) {
      if (this.ctx?.state === 'suspended') await this.ctx.resume().catch(() => {})
      return
    }
    const Ctx = window.AudioContext || window.webkitAudioContext
    if (!Ctx) return
    try {
      this.ctx = new Ctx()
      this.master = this.ctx.createGain()
      this.master.gain.value = this.muted ? 0 : 0.55
      this.master.connect(this.ctx.destination)
      this.ready = true
      if (this.ctx.state === 'suspended') await this.ctx.resume().catch(() => {})
      this.startAmbient()
    } catch {
      this.ready = false
    }
  }

  setMuted(muted) {
    this.muted = muted
    if (!this.ready) return
    const t = this.ctx.currentTime
    this.master.gain.cancelScheduledValues(t)
    this.master.gain.setTargetAtTime(muted ? 0 : 0.55, t, 0.04)
  }

  noiseBuffer(duration = 0.5) {
    const rate = this.ctx.sampleRate
    const length = Math.floor(rate * duration)
    const buffer = this.ctx.createBuffer(1, length, rate)
    const data = buffer.getChannelData(0)
    for (let i = 0; i < length; i++) data[i] = Math.random() * 2 - 1
    return buffer
  }

  noise({ duration = 0.25, gain = 0.2, freq = 1200, type = 'lowpass', when = 0, q = 0.7 }) {
    if (!this.ready || this.muted) return
    const t = this.ctx.currentTime + when
    const src = this.ctx.createBufferSource()
    src.buffer = this.noiseBuffer(duration + 0.05)
    const filter = this.ctx.createBiquadFilter()
    filter.type = type
    filter.frequency.setValueAtTime(freq, t)
    filter.Q.value = q
    const g = this.ctx.createGain()
    g.gain.setValueAtTime(0.0001, t)
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, gain), t + 0.006)
    g.gain.exponentialRampToValueAtTime(0.0001, t + duration)
    src.connect(filter)
    filter.connect(g)
    g.connect(this.master)
    src.start(t)
    src.stop(t + duration + 0.1)
  }

  tone({ freq = 440, endFreq = freq, duration = 0.2, gain = 0.08, type = 'sine', when = 0 }) {
    if (!this.ready || this.muted) return
    const t = this.ctx.currentTime + when
    const osc = this.ctx.createOscillator()
    const g = this.ctx.createGain()
    osc.type = type
    osc.frequency.setValueAtTime(freq, t)
    osc.frequency.exponentialRampToValueAtTime(Math.max(20, endFreq), t + duration)
    g.gain.setValueAtTime(0.0001, t)
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, gain), t + 0.012)
    g.gain.exponentialRampToValueAtTime(0.0001, t + duration)
    osc.connect(g)
    g.connect(this.master)
    osc.start(t)
    osc.stop(t + duration + 0.05)
  }

  startAmbient() {
    if (!this.ready || this.ambient) return
    const t = this.ctx.currentTime
    const src = this.ctx.createBufferSource()
    src.buffer = this.noiseBuffer(6)
    src.loop = true
    const filter = this.ctx.createBiquadFilter()
    filter.type = 'lowpass'
    filter.frequency.value = 240
    const g = this.ctx.createGain()
    g.gain.value = 0.028
    const lfo = this.ctx.createOscillator()
    const lfoGain = this.ctx.createGain()
    lfo.frequency.value = 0.08
    lfoGain.gain.value = 0.008
    lfo.connect(lfoGain)
    lfoGain.connect(g.gain)
    src.connect(filter)
    filter.connect(g)
    g.connect(this.master)
    src.start(t)
    lfo.start(t)
    this.ambient = { src, g, lfo }
  }

  click() {
    this.tone({ freq: 620, endFreq: 480, duration: 0.06, gain: 0.035, type: 'square' })
  }

  select() {
    this.tone({ freq: 440, endFreq: 660, duration: 0.08, gain: 0.04, type: 'triangle' })
  }

  shot(kind = 'rifle') {
    if (kind === 'mg') {
      for (let i = 0; i < 4; i++) this.noise({ duration: 0.08, gain: 0.16, freq: 1900, when: i * 0.055 })
      this.tone({ freq: 120, endFreq: 60, duration: 0.15, gain: 0.04, when: 0.12 })
    } else if (kind === 'cannon') {
      this.noise({ duration: 0.4, gain: 0.3, freq: 340 })
      this.tone({ freq: 110, endFreq: 38, duration: 0.42, gain: 0.15 })
    } else if (kind === 'mortar') {
      this.tone({ freq: 150, endFreq: 50, duration: 0.2, gain: 0.08 })
      this.noise({ duration: 0.5, gain: 0.24, freq: 400, when: 0.08 })
    } else if (kind === 'rpg') {
      this.noise({ duration: 0.32, gain: 0.16, freq: 2600, type: 'bandpass', q: 1.2 })
      this.tone({ freq: 280, endFreq: 90, duration: 0.25, gain: 0.05 })
    } else {
      this.noise({ duration: 0.14, gain: 0.16, freq: 1800, type: 'highpass' })
      this.tone({ freq: 160, endFreq: 80, duration: 0.12, gain: 0.03 })
    }
  }

  explosion(big = false) {
    this.noise({ duration: big ? 0.9 : 0.5, gain: big ? 0.38 : 0.25, freq: big ? 240 : 380 })
    this.tone({ freq: big ? 90 : 120, endFreq: 30, duration: big ? 0.8 : 0.45, gain: big ? 0.17 : 0.1 })
  }

  helicopter() {
    for (let i = 0; i < 8; i++) {
      this.noise({ duration: 0.1, gain: 0.06, freq: 180, type: 'lowpass', when: i * 0.11 })
    }
    this.tone({ freq: 70, endFreq: 65, duration: 0.9, gain: 0.035, type: 'sawtooth' })
  }

  heal() {
    this.tone({ freq: 520, endFreq: 780, duration: 0.18, gain: 0.05, type: 'sine' })
    this.tone({ freq: 780, endFreq: 1040, duration: 0.22, gain: 0.04, type: 'sine', when: 0.12 })
  }

  turn() {
    this.tone({ freq: 720, endFreq: 720, duration: 0.09, gain: 0.035, type: 'square' })
    this.tone({ freq: 960, endFreq: 960, duration: 0.08, gain: 0.025, type: 'square', when: 0.12 })
  }

  warning() {
    this.tone({ freq: 320, endFreq: 300, duration: 0.2, gain: 0.04, type: 'sawtooth' })
  }

  victory() {
    const notes = [392, 523, 659, 784]
    notes.forEach((f, i) => this.tone({ freq: f, endFreq: f, duration: 0.65, gain: 0.07, type: 'triangle', when: i * 0.15 }))
  }

  defeat() {
    this.tone({ freq: 180, endFreq: 60, duration: 1.4, gain: 0.09, type: 'sawtooth' })
    this.noise({ duration: 1.2, gain: 0.06, freq: 200 })
  }
}

import { Game } from './engine.js'
import { MAX_TURNS, SUPPORTS, UNIT_TYPES, PLAYER_ORDER } from './data.js'
import { Renderer } from './render.js'
import { portraitDataURL } from './render-utils.js'
import { AudioSystem } from './audio.js'

const $ = id => document.getElementById(id)
const ui = {
  selectedId: null,
  hover: null,
  mode: null,
  busy: false,
  started: false
}
const coarsePointer = window.matchMedia?.('(pointer: coarse)').matches || false
let game = null
let renderer = null
let audio = null
let activeToastTimer = null
let bannerTimer = null

function loadSetting(key, fallback) {
  try {
    const value = localStorage.getItem(key)
    return value == null ? fallback : JSON.parse(value)
  } catch {
    return fallback
  }
}

function saveSetting(key, value) {
  try { localStorage.setItem(key, JSON.stringify(value)) } catch { /* storage can be unavailable */ }
}

function escapeHtml(value) {
  return String(value)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#039;')
}

function unsuppressKey() {
  return 'firebase-raven-best'
}

// ---------------------------------------------------------------------------
// Engine event routing
// ---------------------------------------------------------------------------

function handleEvent(event) {
  if (!game) return
  if (renderer) renderer.handleEvent(event)
  const sound = audio
  if (sound) {
    if (event.type === 'attack') {
      const w = event.weapon || ''
      if (/M60|M2/.test(w)) sound.shot('mg')
      else if (/90mm|76\.2/.test(w)) sound.shot('cannon')
      else if (/mortar/i.test(w)) sound.shot('mortar')
      else if (/RPG/.test(w)) sound.shot('rpg')
      else sound.shot('rifle')
      if (event.killed) sound.explosion(false)
    } else if (event.type === 'death') {
      sound.explosion(false)
    } else if (event.type === 'support') {
      if (event.kind === 'artillery') sound.explosion(true)
      else if (event.kind === 'huey') { sound.helicopter(); setTimeout(() => sound.explosion(true), 380) }
      else if (event.kind === 'dustoff') sound.heal()
    } else if (event.type === 'spawn') {
      sound.warning()
    } else if (event.type === 'turnStart' && !event.first) {
      sound.turn()
    } else if (event.type === 'gameOver') {
      if (event.result === 'victory') sound.victory()
      else sound.defeat()
    }
  }

  if (event.type === 'turnStart') {
    if (!event.first && ui.started) showTurnBanner(event.turn, event.spawned?.length ? 'ENEMY REINFORCEMENTS INBOUND' : 'HOLD THE PERIMETER')
  }
  if (event.type === 'phase' && event.phase === 'enemy' && ui.started) {
    showPhaseBanner()
  }
  if (event.type === 'gameOver') {
    setTimeout(() => showResult(event), 950)
  }
  if (event.type === 'state' || event.type === 'phase' || event.type === 'turnStart' || event.type === 'log' || event.type === 'spawn' || event.type === 'gameOver') {
    syncUI()
  }
}

function setupGame(seed = Date.now()) {
  game = new Game({ seed, onEvent: handleEvent })
  game.setDelay(ms => new Promise(resolve => setTimeout(resolve, Math.min(ms, 1400))))
  ui.selectedId = null
  ui.hover = null
  ui.mode = null
  ui.busy = false
  if (renderer) renderer.setGame(game)
  syncUI()
}

// ---------------------------------------------------------------------------
// UI sync
// ---------------------------------------------------------------------------

const PHASE_LABEL = {
  briefing: 'BRIEFING',
  player: 'PLAYER',
  enemy: 'ENEMY',
  over: 'COMPLETE'
}

function syncUI() {
  if (!game) return
  const bunker = game.getBunker()
  const bunkerHp = bunker?.alive ? bunker.hp : 0
  const bunkerMax = bunker?.maxHp || 18
  $('hud-turn').innerHTML = `${String(game.turn).padStart(2, '0')}<span>/${MAX_TURNS}</span>`
  $('hud-phase').textContent = PHASE_LABEL[game.phase] || game.phase.toUpperCase()
  $('hud-phase').className = `phase-${game.phase}`
  $('hud-cp').textContent = `${game.cp} CP`
  $('hud-bunker').textContent = `${bunkerHp}/${bunkerMax}`
  $('hud-bunker').className = bunkerHp <= 5 ? 'critical' : bunkerHp <= 10 ? 'warn' : ''

  const turnsLeft = Math.max(0, MAX_TURNS - game.turn + (game.phase === 'over' ? 0 : 1))
  $('objective-sub').textContent = game.phase === 'over'
    ? (game.result === 'victory' ? 'Firebase held until relief' : 'Firebase lost')
    : turnsLeft <= 1 ? 'Relief column is at the wire' : `Relief arrives in ${turnsLeft} turns`
  $('relief-turns').textContent = game.phase === 'over'
    ? (game.result === 'victory' ? 'ARRIVED' : 'FAILED')
    : `${turnsLeft} ${turnsLeft === 1 ? 'TURN' : 'TURNS'}`
  $('bunker-status').textContent = bunkerHp <= 0 ? 'DESTROYED' : bunkerHp <= 5 ? 'CRITICAL' : bunkerHp <= 10 ? 'DAMAGED' : 'NOMINAL'
  $('bunker-status').className = bunkerHp <= 5 ? 'critical' : bunkerHp <= 10 ? 'warn' : ''
  $('mission-progress-fill').style.width = `${Math.max(0, Math.min(100, (bunkerHp / bunkerMax) * 100))}%`
  $('stat-kills').textContent = game.stats.kills
  $('stat-losses').textContent = game.stats.losses
  $('log-count').textContent = String(game.logEntries.length).padStart(2, '0')
  $('cp-value').textContent = game.cp
  renderCpPips()

  renderRoster()
  renderUnitStrip()
  renderSelection()
  renderSupportButtons()
  renderLog()
  renderWaveIntel()
  renderEndTurn()
  renderDrawerState()
  document.body.classList.toggle('is-busy', !!ui.busy)
}

function renderCpPips() {
  const wrap = $('cp-pips')
  if (!wrap) return
  const pips = []
  for (let i = 0; i < 10; i++) pips.push(`<i class="${i < game.cp ? 'on' : ''}"></i>`)
  wrap.innerHTML = pips.join('')
}

function statusFor(unit) {
  if (!unit.alive) return { text: 'DESTROYED', cls: 'dead' }
  if (unit.objective) return { text: unit.hp <= 5 ? 'CRITICAL' : 'OBJECTIVE', cls: unit.hp <= 5 ? 'critical' : 'objective' }
  if (unit.attacked) return { text: 'SPENT', cls: 'spent' }
  if (unit.moved) return { text: 'FIRED?', cls: 'moved' }
  if (unit.suppressed) return { text: 'PINNED', cls: 'pinned' }
  return { text: 'READY', cls: 'ready' }
}

function renderRoster() {
  const list = $('unit-list')
  if (!list) return
  const units = PLAYER_ORDER
    .map(type => game.units.find(u => u.side === 'us' && u.type === type && u.alive) || game.units.find(u => u.side === 'us' && u.type === type))
    .filter(Boolean)
  list.innerHTML = units.map(unit => {
    const status = statusFor(unit)
    const selected = ui.selectedId === unit.id
    const hp = Math.max(0, unit.hp)
    const pct = Math.round((hp / unit.maxHp) * 100)
    return `
      <button class="unit-card ${selected ? 'selected' : ''} ${status.cls} ${unit.objective ? 'objective' : ''}" data-unit-id="${unit.id}" ${unit.alive ? '' : 'disabled'} aria-pressed="${selected}" title="${escapeHtml(unit.name)} — ${escapeHtml(unit.weapon)}">
        <img class="uc-portrait" src="${portraitDataURL(unit.type, 'us')}" alt="" draggable="false">
        <span class="uc-main">
          <span class="uc-top"><strong>${escapeHtml(unit.label)}</strong><em class="state-pill ${status.cls}">${status.text}</em></span>
          <span class="uc-weapon">${escapeHtml(unit.weapon)}</span>
          <span class="uc-hp-track"><i style="width:${pct}%"></i></span>
          <span class="uc-meta"><span>${hp}/${unit.maxHp} HP</span><span>${unit.armor ? `ARM ${unit.armor}` : `MOVE ${unit.move}`} · RNG ${unit.range || '—'}</span></span>
        </span>
      </button>`
  }).join('')
}

function renderUnitStrip() {
  const strip = $('unit-strip')
  if (!strip) return
  const units = game.aliveUnits('us').filter(u => !u.objective)
  strip.innerHTML = units.map(unit => {
    const selected = ui.selectedId === unit.id
    const pct = Math.round((unit.hp / unit.maxHp) * 100)
    const status = statusFor(unit)
    return `<button class="strip-unit ${selected ? 'selected' : ''} ${status.cls}" data-unit-id="${unit.id}" aria-pressed="${selected}" aria-label="${escapeHtml(unit.name)}, ${unit.hp} of ${unit.maxHp} HP">
      <img src="${portraitDataURL(unit.type, 'us')}" alt="" draggable="false">
      <span class="strip-hp"><i style="width:${pct}%"></i></span>
      <b>${escapeHtml(unit.label)}</b>
    </button>`
  }).join('')
}

function selectedUnit() {
  return game.getUnit(ui.selectedId)
}

function renderSelection() {
  const unit = selectedUnit()
  const empty = $('sel-empty')
  const content = $('sel-content')
  if (!unit) {
    empty.classList.remove('hidden')
    content.classList.add('hidden')
    empty.querySelector('p').textContent = game.phase === 'enemy'
      ? 'Enemy movement in progress. Hold the line.'
      : game.phase === 'over'
        ? 'The engagement is over. Redeploy to try another defence.'
        : 'Select a unit on the map or in the order of battle.'
    return
  }
  empty.classList.add('hidden')
  content.classList.remove('hidden')
  const sideLabel = unit.side === 'us' ? (unit.objective ? 'OBJECTIVE' : 'FRIENDLY') : 'ENEMY CONTACT'
  const status = statusFor(unit)
  $('sel-portrait').src = portraitDataURL(unit.type, unit.side)
  $('sel-name').textContent = unit.name
  $('sel-weapon').textContent = `${sideLabel} · ${unit.weapon}`
  const atk = unit.armor ? `${unit.soft}/${unit.armorAtk}` : `${unit.soft} soft`
  $('sel-stats').innerHTML = `
    <span><b>HP</b> ${unit.hp}/${unit.maxHp}</span>
    <span><b>FIRE</b> ${unit.range ? `${atk} · RNG ${unit.range}` : '—'}</span>
    <span><b>MOVE</b> ${unit.move || '—'}</span>
    <span><b>COVER</b> +${game.coverOf(unit)}</span>
    <span class="sel-state ${status.cls}">${status.text}</span>
  `
  $('sel-hpfill').style.width = `${Math.max(0, (unit.hp / unit.maxHp) * 100)}%`
  $('sel-hpfill').className = unit.hp / unit.maxHp <= 0.3 ? 'low' : unit.hp / unit.maxHp <= 0.6 ? 'mid' : ''
  $('sel-hp').textContent = `${unit.hp}/${unit.maxHp}`
  $('selection-card').classList.toggle('enemy-selected', unit.side === 'nva')
}

function renderSupportButtons() {
  for (const kind of Object.keys(SUPPORTS)) {
    const btn = document.querySelector(`[data-support="${kind}"]`)
    if (!btn) continue
    const def = SUPPORTS[kind]
    const charges = game.supportCharges[kind]
    const costEl = btn.querySelector('em')
    if (costEl) costEl.textContent = `${def.cost} CP · ${charges}`
    btn.disabled = !game.supportAvailable(kind) || ui.busy || game.phase !== 'player'
    btn.classList.toggle('active', ui.mode?.kind === kind)
    btn.setAttribute('aria-pressed', ui.mode?.kind === kind ? 'true' : 'false')
    btn.title = def.desc
  }
}

function renderLog() {
  const log = $('log')
  if (!log) return
  const entries = game.logEntries.slice(-45).reverse()
  log.innerHTML = entries.map(entry => `
    <div class="log-entry kind-${entry.kind}">
      <span class="log-meta">T${String(entry.turn).padStart(2, '0')} · ${entry.time}</span>
      <p>${escapeHtml(entry.text)}</p>
    </div>`).join('')
}

function renderWaveIntel() {
  const box = $('next-wave-content')
  if (!box) return
  if (game.phase === 'over') {
    box.innerHTML = `<div class="wave-final">${game.result === 'victory' ? 'RELIEF COLUMN ARRIVED' : 'NO FURTHER CONTACTS'}</div>`
    return
  }
  if (game.turn >= MAX_TURNS) {
    box.innerHTML = `<div class="wave-final victory">RELIEF COLUMN INBOUND<br><span>Hold until end of turn</span></div>`
    return
  }
  const wave = game.nextWave()
  const turn = game.turn + 1
  if (!wave.length) {
    box.innerHTML = `<div class="wave-final"><span>INBOUND T${String(turn).padStart(2, '0')}</span><br>No further movement detected</div>`
    return
  }
  const counts = new Map()
  for (const spec of wave) counts.set(spec.type, (counts.get(spec.type) || 0) + 1)
  const items = [...counts.entries()].map(([type, count]) => {
    const def = UNIT_TYPES[type]
    return `<div class="wave-unit"><img src="${portraitDataURL(type, 'nva')}" alt="" draggable="false"><span><b>${count}× ${escapeHtml(def.callsign)}</b><small>${escapeHtml(def.weapon)}</small></span></div>`
  }).join('')
  box.innerHTML = `<div class="wave-turn">INBOUND T${String(turn).padStart(2, '0')}</div><div class="wave-list">${items}</div>`
}

function renderEndTurn() {
  const btn = $('btn-end-turn')
  if (!btn) return
  const ready = game.readyUnits().length
  if (game.phase === 'player') {
    btn.disabled = ui.busy
    btn.querySelector('.end-turn-label').textContent = 'END TURN'
    $('end-turn-sub').textContent = ready ? `${ready} ${ready === 1 ? 'UNIT' : 'UNITS'} READY` : 'ALL UNITS COMMITTED'
  } else if (game.phase === 'enemy') {
    btn.disabled = true
    btn.querySelector('.end-turn-label').textContent = 'ENEMY PHASE'
    $('end-turn-sub').textContent = 'MOVEMENT IN PROGRESS'
  } else {
    btn.disabled = true
    btn.querySelector('.end-turn-label').textContent = 'OPERATION OVER'
    $('end-turn-sub').textContent = game.result === 'victory' ? 'FIREBASE HELD' : 'FIREBASE LOST'
  }
}

function renderDrawerState() {
  document.body.classList.toggle('drawer-roster', false)
  document.body.classList.toggle('drawer-log', false)
}

// ---------------------------------------------------------------------------
// Board interactions
// ---------------------------------------------------------------------------

function selectUnit(id, { toggle = true, sound = true } = {}) {
  if (ui.busy) return
  if (toggle && ui.selectedId === id && !ui.mode) {
    ui.selectedId = null
  } else {
    ui.selectedId = id
    ui.mode = null
    hideTargetPrompt()
  }
  if (sound) audio?.select()
  syncUI()
}

function clearSelection() {
  ui.selectedId = null
  ui.mode = null
  hideTargetPrompt()
  syncUI()
}

function startTargetMode(kind) {
  if (ui.busy || game.phase !== 'player') return
  if (!game.supportAvailable(kind)) {
    toast(kind === 'dustoff' ? 'No medevac sorties remaining.' : 'Not enough command points or sorties remaining.', 'warning')
    return
  }
  if (ui.mode?.kind === kind) {
    cancelTargetMode()
    return
  }
  ui.mode = { kind, staged: null }
  ui.selectedId = null
  ui.hover = null
  renderer.events = null
  const text = kind === 'artillery'
    ? 'Select the impact hex · 105mm battery standing by'
    : kind === 'huey'
      ? 'Select the strafe hex · UH-1B gunship on station'
      : 'Select a friendly unit to evacuate'
  $('target-text').textContent = text
  $('target-prompt').classList.remove('hidden')
  document.body.classList.add('targeting')
  audio?.select()
  syncUI()
}

function cancelTargetMode() {
  ui.mode = null
  $('target-prompt').classList.add('hidden')
  document.body.classList.remove('targeting')
  syncUI()
}

function hideTargetPrompt() {
  $('target-prompt').classList.add('hidden')
  document.body.classList.remove('targeting')
}

async function executeSupport(cell, unit) {
  const kind = ui.mode.kind
  if (kind === 'dustoff' && (!unit || unit.side !== 'us' || unit.objective)) {
    toast('Medevac must target a friendly combat unit.', 'warning')
    audio?.warning()
    return
  }
  if (coarsePointer && ui.mode.staged !== `${cell.c},${cell.r}`) {
    ui.mode.staged = `${cell.c},${cell.r}`
    ui.hover = { c: cell.c, r: cell.r }
    $('target-text').textContent = 'Tap the same hex again to confirm'
    updateTooltipForCell(cell, unit, null)
    syncUI()
    return
  }

  ui.mode = null
  hideTargetPrompt()
  ui.hover = null
  ui.busy = true
  syncUI()
  try {
    if (kind === 'artillery') await game.callArtillery(cell.c, cell.r)
    else if (kind === 'huey') await game.callHuey(cell.c, cell.r)
    else if (kind === 'dustoff') await game.callDustoff(unit.id)
  } finally {
    ui.busy = false
    syncUI()
  }
}

async function doMove(unit, cell) {
  ui.busy = true
  ui.hover = { c: cell.c, r: cell.r }
  syncUI()
  try {
    await game.movePlayerUnit(unit.id, cell.c, cell.r)
  } finally {
    ui.busy = false
    syncUI()
  }
}

async function doAttack(attacker, target) {
  ui.busy = true
  syncUI()
  try {
    await game.attack(attacker.id, target.id)
  } finally {
    ui.busy = false
    syncUI()
  }
}

function onBoardPointerDown(event) {
  if (event.pointerType === 'mouse' && event.button !== 0) return
  if (!ui.started || ui.busy) return
  if (document.body.classList.contains('is-busy')) return
  const cell = renderer.pickHex(event.clientX, event.clientY)
  if (!cell) return
  const unit = game.occupied(cell.c, cell.r)

  if (ui.mode) {
    executeSupport(cell, unit)
    return
  }
  if (game.phase !== 'player') {
    if (unit) selectUnit(unit.id)
    return
  }

  const selected = selectedUnit()
  if (unit && unit.side === 'us') {
    selectUnit(unit.id)
    return
  }
  if (selected && selected.side === 'us' && unit && unit.side === 'nva') {
    if (game.inAttackRange(selected, unit) && !selected.attacked && !selected.cannotAct) {
      doAttack(selected, unit)
    } else {
      toast(`${unit.name} is outside ${selected.label}'s engagement range.`, 'warning')
      audio?.warning()
    }
    return
  }
  if (selected && selected.side === 'us' && !selected.moved && !selected.attacked && !selected.cannotAct && game.canMoveTo(selected, cell.c, cell.r)) {
    if (cell.c === selected.c && cell.r === selected.r) {
      syncUI()
      return
    }
    doMove(selected, cell)
    return
  }
  if (unit) {
    selectUnit(unit.id)
    return
  }
  clearSelection()
}

function onBoardPointerMove(event) {
  if (event.pointerType !== 'mouse' || !ui.started) return
  const cell = renderer.pickHex(event.clientX, event.clientY)
  ui.hover = cell
  if (!cell) {
    hideTooltip()
    return
  }
  const unit = game.occupied(cell.c, cell.r)
  updateTooltipForCell(cell, unit, event)
}

function updateTooltipForCell(cell, unit, event) {
  const tip = $('tooltip')
  if (!tip) return
  const terrain = game.constructor ? null : null
  const t = (awaitTerrain(cell.c, cell.r))
  const selected = selectedUnit()
  let html = `<div class="tip-head"><b>${t.name}</b><span>${coordLabel(cell.c, cell.r)}</span></div>
    <div class="tip-sub">MOVE ${t.impassable ? '—' : t.move} · COVER +${t.cover}</div>
    <p>${escapeHtml(t.detail)}</p>`

  if (unit) {
    const side = unit.side === 'us' ? 'FRIENDLY' : 'ENEMY'
    const status = statusFor(unit)
    html += `<div class="tip-unit ${unit.side}">
      <div class="tip-unit-head"><b>${escapeHtml(unit.name)}</b><span>${side}</span></div>
      <div class="tip-grid">
        <span>HP <b>${unit.hp}/${unit.maxHp}</b></span>
        <span>FIRE <b>${unit.soft}/${unit.armorAtk}</b></span>
        <span>RNG <b>${unit.range || '—'}</b></span>
        <span>COVER <b>+${game.coverOf(unit)}</b></span>
      </div>
      <div class="tip-weapon">${escapeHtml(unit.weapon)} ${status.text === 'READY' ? '' : `· ${status.text}`}</div>`
    if (selected && selected.side === 'us' && unit.side === 'nva' && game.inAttackRange(selected, unit) && !selected.attacked) {
      html += `<div class="tip-damage">EST. ${game.estimateDamage(selected, unit)} DMG · CLICK TO FIRE</div>`
    } else if (selected && selected.side === 'us' && unit.side === 'nva' && selected.attacked) {
      html += `<div class="tip-damage muted">ALREADY FIRED THIS TURN</div>`
    }
    html += '</div>'
  } else if (selected && selected.side === 'us' && game.canMoveTo(selected, cell.c, cell.r) && !selected.attacked) {
    html += `<div class="tip-action">CLICK TO MOVE HERE</div>`
  }

  if (ui.mode) {
    const preview = game.previewSupport(ui.mode.kind, cell.c, cell.r)
    if (ui.mode.kind === 'dustoff') {
      html += `<div class="tip-action ${preview.length ? 'good' : 'bad'}">${preview.length ? 'CLICK TO MEDEVAC THIS UNIT' : 'SELECT A FRIENDLY COMBAT UNIT'}</div>`
    } else {
      const enemies = preview.filter(p => p.side === 'nva').length
      const friendlies = preview.filter(p => p.friendly).length
      html += `<div class="tip-action ${friendlies ? 'bad' : enemies ? 'good' : ''}">${enemies} ENEMY · ${friendlies} FRIENDLY IN BLAST${friendlies ? ' · DANGER CLOSE' : ''}</div>`
    }
  }

  tip.innerHTML = html
  tip.classList.remove('hidden')
  if (event) {
    const pad = 16
    const vw = window.innerWidth
    const vh = window.innerHeight
    const w = tip.offsetWidth
    const h = tip.offsetHeight
    let x = event.clientX + pad
    let y = event.clientY + pad
    if (x + w > vw - 10) x = event.clientX - w - pad
    if (y + h > vh - 10) y = event.clientY - h - pad
    tip.style.left = `${Math.max(8, x)}px`
    tip.style.top = `${Math.max(8, y)}px`
  }
}

function awaitTerrain(c, r) {
  // Imported lazily through the data module to keep tooltip code compact.
  return TERRAIN_BY_CELL(c, r)
}

import { terrainAt, coordLabel } from './engine.js'
import { TERRAIN as TERRAIN_TABLE } from './data.js'

function TERRAIN_BY_CELL(c, r) {
  return terrainAt(c, r) || TERRAIN_TABLE.grass
}

function hideTooltip() {
  $('tooltip')?.classList.add('hidden')
}

// ---------------------------------------------------------------------------
// Turn flow / outcomes
// ---------------------------------------------------------------------------

async function endTurn() {
  if (ui.busy || game.phase !== 'player' || !ui.started) return
  ui.mode = null
  ui.hover = null
  hideTargetPrompt()
  hideTooltip()
  ui.busy = true
  syncUI()
  audio?.turn()
  try {
    await game.endPlayerTurn()
  } finally {
    ui.busy = false
    syncUI()
  }
}

function showTurnBanner(turn, subtitle) {
  const banner = $('turn-banner')
  if (!banner) return
  banner.querySelector('span').textContent = `TURN ${String(turn).padStart(2, '0')} / ${MAX_TURNS}`
  banner.querySelector('strong').textContent = subtitle
  banner.classList.remove('hidden')
  banner.classList.add('show')
  clearTimeout(bannerTimer)
  bannerTimer = setTimeout(() => {
    banner.classList.remove('show')
    setTimeout(() => banner.classList.add('hidden'), 450)
  }, 1450)
}

function showPhaseBanner() {
  const banner = $('turn-banner')
  if (!banner) return
  banner.querySelector('span').textContent = 'ENEMY MOVEMENT'
  banner.querySelector('strong').textContent = 'HOLD THE LINE'
  banner.classList.remove('hidden')
  banner.classList.add('show')
  clearTimeout(bannerTimer)
  bannerTimer = setTimeout(() => {
    banner.classList.remove('show')
    setTimeout(() => banner.classList.add('hidden'), 450)
  }, 900)
}

function showResult(event) {
  const best = Number(loadSetting(unsuppressKey(), 0)) || 0
  const isBest = event.score > best
  if (isBest) saveSetting(unsuppressKey(), event.score)
  const modal = $('result-modal')
  const victory = event.result === 'victory'
  modal.querySelector('.result-grade').textContent = event.grade
  modal.querySelector('.result-title').textContent = victory ? 'FIREBASE HELD' : 'FIREBASE OVERRUN'
  modal.querySelector('.result-kicker').textContent = victory ? 'MISSION ACCOMPLISHED' : 'MISSION FAILED'
  modal.querySelector('.result-reason').textContent = event.reason
  modal.querySelector('.result-score').textContent = event.score.toLocaleString()
  modal.querySelector('.result-best').textContent = isBest ? 'NEW BEST' : `BEST ${best.toLocaleString()}`
  modal.querySelector('.result-stats').innerHTML = `
    <div><span>ENEMY DESTROYED</span><b>${event.stats.kills}</b></div>
    <div><span>FRIENDLY LOSSES</span><b>${event.stats.losses}</b></div>
    <div><span>BUNKER HP</span><b>${event.stats.bunkerHp}</b></div>
    <div><span>TURNS HELD</span><b>${event.stats.turns}</b></div>
    <div><span>ARTILLERY / AIR</span><b>${event.stats.supportUses}</b></div>
    <div><span>ENEMIES ENGAGED</span><b>${event.stats.enemiesSpawned}</b></div>
  `
  modal.querySelector('.result-shell').classList.toggle('victory', victory)
  modal.querySelector('.result-shell').classList.toggle('defeat', !victory)
  modal.classList.remove('hidden')
  document.body.classList.add('result-open')
}

function startOperation() {
  if (game.phase !== 'briefing') return
  audio?.unlock()
  audio?.click()
  game.start()
  ui.started = true
  $('start-modal').classList.add('hidden')
  document.getElementById('app').classList.add('in-game')
  syncUI()
}

function restartOperation() {
  audio?.unlock()
  audio?.click()
  $('result-modal').classList.add('hidden')
  $('manual-modal').classList.add('hidden')
  $('start-modal').classList.add('hidden')
  document.body.classList.remove('result-open')
  setupGame(Date.now())
  game.start()
  ui.started = true
  document.getElementById('app').classList.add('in-game')
  syncUI()
  showTurnBanner(1, 'HOLD THE PERIMETER')
  toast('New operation started. Firebase Raven is standing by.', 'system')
}

function openManual() {
  audio?.unlock()
  audio?.click()
  $('manual-modal').classList.remove('hidden')
}

function closeManual() {
  $('manual-modal').classList.add('hidden')
}

function closeResult() {
  $('result-modal').classList.add('hidden')
  document.body.classList.remove('result-open')
}

function toast(text, kind = '') {
  const stack = $('toast-stack')
  if (!stack) return
  const el = document.createElement('div')
  el.className = `toast ${kind}`
  el.textContent = text
  stack.appendChild(el)
  while (stack.children.length > 3) stack.firstElementChild.remove()
  requestAnimationFrame(() => el.classList.add('in'))
  setTimeout(() => {
    el.classList.remove('in')
    setTimeout(() => el.remove(), 300)
  }, 2800)
}

// ---------------------------------------------------------------------------
// Wiring
// ---------------------------------------------------------------------------

function bind() {
  $('btn-start').addEventListener('click', startOperation)
  $('btn-brief-manual').addEventListener('click', openManual)
  $('btn-manual').addEventListener('click', openManual)
  $('btn-restart').addEventListener('click', restartOperation)
  $('btn-end-turn').addEventListener('click', endTurn)
  $('btn-cancel-target').addEventListener('click', cancelTargetMode)
  $('btn-sound').addEventListener('click', () => {
    audio?.unlock()
    const muted = !audio.muted
    audio.setMuted(muted)
    saveSetting('firebase-raven-muted', muted)
    updateSoundButton()
    if (!muted) audio?.click()
  })

  for (const btn of document.querySelectorAll('[data-support]')) {
    btn.addEventListener('click', () => startTargetMode(btn.dataset.support))
  }
  for (const btn of document.querySelectorAll('[data-close-manual]')) btn.addEventListener('click', closeManual)
  for (const btn of document.querySelectorAll('[data-close-result]')) btn.addEventListener('click', closeResult)
  $('btn-result-restart').addEventListener('click', restartOperation)
  $('manual-modal').addEventListener('click', event => {
    if (event.target === $('manual-modal')) closeManual()
  })
  $('result-modal').addEventListener('click', event => {
    if (event.target === $('result-modal')) closeResult()
  })
  $('start-modal').addEventListener('click', event => {
    if (event.target === $('start-modal')) return
  })

  $('btn-units-mobile').addEventListener('click', () => {
    document.body.classList.toggle('drawer-roster')
    document.body.classList.remove('drawer-log')
  })
  $('btn-log-mobile').addEventListener('click', () => {
    document.body.classList.toggle('drawer-log')
    document.body.classList.remove('drawer-roster')
  })
  for (const btn of document.querySelectorAll('[data-close-drawer]')) {
    btn.addEventListener('click', () => {
      document.body.classList.remove('drawer-roster', 'drawer-log')
    })
  }

  const canvas = $('board')
  canvas.addEventListener('pointerdown', onBoardPointerDown)
  canvas.addEventListener('pointermove', onBoardPointerMove)
  canvas.addEventListener('pointerleave', () => {
    ui.hover = null
    hideTooltip()
  })
  canvas.addEventListener('contextmenu', event => event.preventDefault())

  document.addEventListener('keydown', event => {
    if (event.key === 'Escape') {
      if (!$('manual-modal').classList.contains('hidden')) { closeManual(); return }
      if (!$('result-modal').classList.contains('hidden')) { closeResult(); return }
      if (ui.mode) { cancelTargetMode(); return }
      if (ui.selectedId) { clearSelection(); return }
    }
    if ($('start-modal').classList.contains('hidden') === false && (event.key === 'Enter' || event.key === ' ')) {
      event.preventDefault()
      startOperation()
      return
    }
    if (!ui.started || ui.busy) return
    const key = event.key.toLowerCase()
    if (key === 'e') { event.preventDefault(); endTurn() }
    else if (key === 'a') startTargetMode('artillery')
    else if (key === 'h') startTargetMode('huey')
    else if (key === 'm') startTargetMode('dustoff')
    else if (key === '?') openManual()
    else if (/^[1-6]$/.test(key)) {
      const index = Number(key) - 1
      const type = PLAYER_ORDER[index]
      const unit = game.units.find(u => u.side === 'us' && u.type === type && u.alive)
      if (unit) selectUnit(unit.id)
    }
  })

  const roster = $('unit-list')
  roster.addEventListener('click', event => {
    const card = event.target.closest('[data-unit-id]')
    if (!card) return
    selectUnit(card.dataset.unitId)
  })
  const strip = $('unit-strip')
  strip.addEventListener('click', event => {
    const card = event.target.closest('[data-unit-id]')
    if (!card) return
    selectUnit(card.dataset.unitId)
    document.body.classList.remove('drawer-roster')
  })
}

function updateSoundButton() {
  const btn = $('btn-sound')
  if (!btn) return
  const muted = audio?.muted ?? true
  btn.classList.toggle('muted', muted)
  btn.innerHTML = muted ? soundOffIcon() + '<span>SOUND OFF</span>' : soundOnIcon() + '<span>SOUND ON</span>'
  btn.setAttribute('aria-label', muted ? 'Turn sound on' : 'Mute sound')
}

function soundOnIcon() {
  return '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 9v6h4l5 4V5L8 9H4z" fill="currentColor"/><path d="M16 8.5a5 5 0 010 7M18.5 6a8.5 8.5 0 010 12" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg>'
}

function soundOffIcon() {
  return '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 9v6h4l5 4V5L8 9H4z" fill="currentColor"/><path d="M16 9l5 6M21 9l-5 6" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg>'
}

// Debug/QA hook — useful for automated verification and not part of gameplay.
function exposeDebug() {
  window.__RAVEN__ = {
    get game() { return game },
    get ui() { return ui },
    get renderer() { return renderer },
    start: startOperation,
    restart: restartOperation,
    selectUnit,
    move: (id, c, r) => game.movePlayerUnit(id, c, r),
    attack: (attackerId, defenderId) => game.attack(attackerId, defenderId),
    endTurn,
    support: (kind, c, r) => {
      if (kind === 'dustoff') {
        const unit = game.occupied(c, r)
        return game.callDustoff(unit?.id)
      }
      if (kind === 'artillery') return game.callArtillery(c, r)
      return game.callHuey(c, r)
    },
    win: () => game.finish('victory', 'The relief column reached Firebase Raven at first light.'),
    lose: () => game.finish('defeat', 'The command bunker was overrun. Firebase Raven has fallen.'),
    turbo: () => game.setDelay(async () => {}),
    state: () => game.serialize()
  }
}

function boot() {
  const muted = loadSetting('firebase-raven-muted', false)
  audio = new AudioSystem({ muted: Boolean(muted) })
  setupGame(Date.now())
  renderer = new Renderer($('board'), game, ui)
  bind()
  updateSoundButton()
  exposeDebug()
  syncUI()
  hideTooltip()
}

boot()

