import { Game, hexDistance } from '/home/runner/work/PlayGround/PlayGround/js/engine.js'
import { UNIT_TYPES } from '/home/runner/work/PlayGround/PlayGround/js/data.js'

function chooseDestination(game, unit, target) {
  const { costs } = game.reachableMap(unit)
  let best = { c: unit.c, r: unit.r }
  let bestScore = -Infinity
  for (const key of costs.keys()) {
    const [c, r] = key.split(',').map(Number)
    if (game.occupied(c, r, unit.id)) continue
    const d = hexDistance({ c, r }, target)
    const t = game.terrain({ c, r, ...unit })
    let score = -d * 10 + game.coverOf({ ...unit, c, r }) * 1.5
    if (d <= unit.range && d >= (unit.minRange || 0)) score += 30
    const adjacentThreats = game.enemyUnits().filter(e => hexDistance(e, { c, r }) === 1).length
    score -= adjacentThreats * 3
    if (score > bestScore) { bestScore = score; best = { c, r } }
  }
  return best
}

async function play(seed, verbose = false) {
  const game = new Game({ seed })
  game.setDelay(async () => {})
  game.start()
  let guard = 0
  while (game.phase === 'player' && game.turn <= 10 && guard++ < 60) {
    // Supports: artillery on enemy clusters, away from friendlies.
    if (game.supportAvailable('artillery')) {
      let best = null
      for (const e of game.enemyUnits()) {
        const around = game.aliveUnits().filter(u => hexDistance(u, e) <= 1)
        const enemies = around.filter(u => u.side === 'nva').length
        const friendlies = around.filter(u => u.side === 'us').length
        const score = enemies * 10 - friendlies * 20 - (e.hp)
        if (enemies >= 2 && friendlies === 0 && (!best || score > best.score)) best = { c: e.c, r: e.r, score }
      }
      if (best) await game.callArtillery(best.c, best.r)
    }
    if (game.phase !== 'player') break
    if (game.supportAvailable('huey')) {
      let best = null
      for (const e of game.enemyUnits()) {
        const around = game.aliveUnits().filter(u => hexDistance(u, e) <= 1)
        const enemies = around.filter(u => u.side === 'nva').length
        const score = enemies * 10 - e.hp
        if (enemies >= 2 && (!best || score > best.score)) best = { c: e.c, r: e.r, score }
      }
      if (best) await game.callHuey(best.c, best.r)
    }
    if (game.supportAvailable('dustoff')) {
      const hurt = game.playerCombatUnits().filter(u => u.hp <= u.maxHp - 5 && u.hp > 0).sort((a, b) => a.hp - b.hp)[0]
      if (hurt) await game.callDustoff(hurt.id)
    }
    if (game.phase !== 'player') break

    for (const unit of game.playerCombatUnits()) {
      if (!unit.alive || game.phase !== 'player') continue
      let targets = game.targetsInRange(unit)
      if (targets.length) {
        const t = targets.sort((a, b) => {
          const ak = a.hp <= game.estimateDamage(unit, a) ? 100 : 0
          const bk = b.hp <= game.estimateDamage(unit, b) ? 100 : 0
          return (bk - b.hp) - (ak - a.hp)
        })[0]
        await game.attack(unit.id, t.id)
        continue
      }
      if (unit.moved || unit.attacked) continue
      const enemies = game.enemyUnits()
      if (!enemies.length) continue
      const bunker = game.getBunker()
      const nearest = enemies.sort((a, b) => hexDistance(unit, a) - hexDistance(unit, b))[0]
      const dest = chooseDestination(game, unit, nearest)
      if (dest.c !== unit.c || dest.r !== unit.r) {
        await game.movePlayerUnit(unit.id, dest.c, dest.r)
        targets = game.targetsInRange(unit)
        if (targets.length) {
          const t = targets[0]
          await game.attack(unit.id, t.id)
        }
      }
    }
    if (game.phase === 'player' && game.turn <= 10) {
      await game.endPlayerTurn()
    }
  }
  return game
}

const seeds = [1, 2, 3, 4, 5, 42, 99, 1234, 7777, 31337]
let wins = 0
for (const seed of seeds) {
  const g = await play(seed)
  if (g.result === 'victory') wins++
  console.log(`seed ${seed}: ${g.result} turn ${g.turn} score ${g.score} grade ${g.grade} kills ${g.stats.kills} losses ${g.stats.losses} bunker ${g.getBunker()?.hp} cp ${g.cp}`)
}
console.log(`\nWins ${wins}/${seeds.length}`)

import { Game, hexDistance } from '/home/runner/work/PlayGround/PlayGround/js/engine.js'

const game = new Game({ seed: 1 })
game.setDelay(async () => {})
game.start()
console.log('start', game.serialize())
for (let t = 0; t < 2; t++) {
  console.log('\n--- player turn', game.turn, 'phase', game.phase)
  for (const u of game.playerCombatUnits()) {
    const targets = game.targetsInRange(u)
    const reach = game.reachableMap(u)
    console.log(u.label, 'at', u.c, u.r, 'move', u.move, 'range', u.range, 'targets', targets.map(t => t.name), 'reach', [...reach.costs.keys()].length)
    if (!targets.length) {
      const enemies = game.enemyUnits().sort((a,b)=>hexDistance(u,a)-hexDistance(u,b))
      console.log('  nearest enemy', enemies[0]?.name, hexDistance(u, enemies[0]))
    }
  }
  for (const u of game.playerCombatUnits()) {
    const targets = game.targetsInRange(u)
    if (targets.length) {
      const ok = await game.attack(u.id, targets[0].id)
      console.log(' attack', u.label, '->', targets[0].label, ok)
    }
  }
  await game.endPlayerTurn()
  console.log('after enemy: turn', game.turn, 'phase', game.phase, 'turn', game.turn, 'losses', game.stats.losses, 'enemy positions', game.enemyUnits().map(e => `${e.label}@${e.c},${e.r} hp${e.hp}`))
}
